import { PersonaEra, PersonaTerm } from './types';

type FashionPersonaSeed = {
  id: string;
  name: string;
  nameEn: string;
  group: string;
  groupEn: string;
  def: string;
  defEn: string;
  ontologyLevel?: 1 | 2 | 3 | 4 | 5;
  eras?: PersonaEra[];
  risk?: 'clean' | 'medium' | 'high';
  tags?: string[];
  styleTags?: string[];
  controls?: string[];
  forbids?: string[];
  absorptionRule?: string;
  absorptionRuleEn?: string;
};

const baseControls = ['costume', 'material', 'silhouette', 'pose', 'hair', 'makeup', 'symbol'];
const defaultForbids = ['随机战术装备堆叠', '无解释身体异形化', '脏乱废土拼贴', '让服装品牌标志抢走原创角色身份'];
const modernEras: PersonaEra[] = ['modern', 'contemporary', 'timeless'];
const contemporaryEras: PersonaEra[] = ['contemporary', 'near_future', 'timeless'];
const futureEras: PersonaEra[] = ['near_future', 'far_future', 'timeless'];

const fp = (seed: FashionPersonaSeed): PersonaTerm => {
  const ontologyLevel = seed.ontologyLevel ?? 1;
  const eras = seed.eras ?? modernEras;
  const risk = seed.risk ?? (ontologyLevel >= 4 ? 'medium' : 'clean');
  const controls = Array.from(new Set([...baseControls, ...(seed.controls || [])]));
  const styleTags = Array.from(new Set(['fashion', 'couture', ...(seed.styleTags || []), ...(seed.tags || [])]));
  return {
    id: `cd_persona_fashion_${seed.id}`,
    name: seed.name,
    nameEn: seed.nameEn,
    group: seed.group,
    groupEn: seed.groupEn,
    def: seed.def,
    defEn: seed.defEn,
    personaCategory: '时尚 / 高定 / 名流系统',
    personaCategoryEn: 'Fashion / Couture / Celebrity System',
    personaSubgroup: seed.group.replace(/^[A-J]\.\s*/, ''),
    personaSubgroupEn: seed.groupEn.replace(/^[A-J]\.\s*/, ''),
    personaKind: seed.name,
    personaKindEn: seed.nameEn,
    personaStrength: ontologyLevel >= 4 ? 'strong' : ontologyLevel >= 2 ? 'medium' : 'light',
    isCompoundPersona: true,
    ontologyLevel,
    eras,
    risk,
    affects: controls,
    controls,
    forbids: Array.from(new Set([...(seed.forbids || []), ...defaultForbids])),
    absorptionRule: seed.absorptionRule || `外来元素优先折译为“${seed.name}”的服装结构、妆发、姿态、道具、社交位置或媒体图像，不要直接堆成无关职业或怪物器官。`,
    absorptionRuleEn: seed.absorptionRuleEn || `Translate outside elements into the clothing structure, hair/makeup, posture, props, social position, or media image of "${seed.nameEn}"; do not stack them as unrelated jobs or monster organs.`,
    tags: Array.from(new Set(['persona', 'fashion', 'compound_persona', ...(seed.tags || [])])),
    realityTags: ontologyLevel <= 1 ? ['realist_safe'] : ontologyLevel <= 3 ? ['stylized_boundary'] : ['nonreal_ontology'],
    styleTags,
    timeTags: eras
  };
};

const seeds: FashionPersonaSeed[] = [
  { id: 'nineties_supermodel', name: '90年代超模', nameEn: '1990s Supermodel', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是90年代杂志时代的冷脸超模。造型入口：长腿、硬颧骨和极简高定让她像从胶片封面和旧式T台灯光里走出。母题：商业神话化的身体职业。张力：完美可售卖与拒绝亲和之间的冷距离。视觉证据：拉长比例、烟熏后台妆、窄而锋利的服装线和不取悦镜头的表情。边界：避免普通漂亮模特或现代网红。', defEn: 'First read: a cold 1990s magazine-era supermodel. Styling entry: long legs, hard cheekbones, and minimal couture as if stepping out of film covers and old runway light. Motif: the commercially mythologized professional body. Tension: sellable perfection held at a cold distance from approachability. Visual evidence: elongated proportion, backstage smoky makeup, narrow sharp clothing, and a face that does not please the camera. Boundary: avoid a generic pretty model or modern influencer.', tags: ['supermodel', 'runway', '90s'], eras: ['modern', 'timeless'] },
  { id: 'couture_muse', name: '高定缪斯', nameEn: 'Couture Muse', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是被高定系统选中的活体缪斯，不是单纯穿漂亮衣服的人。造型入口：被高定系统选中的活体缪斯，不是单纯穿漂亮衣服的人。母题：设计师欲望的身体载体。张力：主体存在感被服装压过，却仍要保留一个安静、难以替代的人格中心。视觉证据：夸张衣量、实验剪裁、非日常站姿和近乎空白的表情。边界：避免把她写成普通礼服模特或品牌展示架。', defEn: 'First read: a living muse chosen by a couture system, not merely someone in beautiful clothes. Styling entry: a living muse chosen by a couture system, not merely someone in beautiful clothes. Motif: the body-carrier of a designer’s desire. Tension: the garment may overpower the subject while a quiet, irreplaceable personhood still remains. Visual evidence: extreme volume, experimental cut, non-daily stance, and an almost blank expression. Boundary: avoid reduce her to a generic gown model or brand mannequin.', tags: ['muse', 'couture', 'designer'] },
  { id: 'runway_finale_gown_model', name: '压轴礼服模特', nameEn: 'Finale Gown Runway Model', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是秀场最后一套礼服的仪式中心。造型入口：秀场最后一套礼服的仪式中心。母题：被全场凝视托起的压轴身体。张力：她必须像胜利者一样出现，却几乎被礼服重量、拖尾和珠绣反光拖住。视觉证据：巨大裙摆、慢而稳的步伐、被压低的肩颈和全场观看压力。边界：避免只写成漂亮婚纱或普通礼服展示。', defEn: 'First read: the ritual center of the final runway gown. Styling entry: the ritual center of the final runway gown. Motif: a finale body lifted by the room’s gaze. Tension: she must appear victorious while almost being held back by gown weight, train, and beadwork reflection. Visual evidence: enormous skirt mass, slow steady walk, lowered neck-shoulder line, and the pressure of being watched. Boundary: avoid making it merely a pretty bridal or generic gown display.', tags: ['finale', 'gown', 'runway'] },
  { id: 'avant_garde_runway_alien', name: '先锋异脸秀场模特', nameEn: 'Avant-Garde Alien-Face Runway Model', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是被秀场美学异化的人形模特，而不是怪物。造型入口：被秀场美学异化的人形模特，而不是怪物。母题：“高定把人脸改造成外星界面”。张力：非人感必须来自时装语言，同时身体仍保持可读的人类模特结构。视觉证据：冷白底妆、拉长眼型、雕塑服装、机械台步和材料反光。边界：避免生成真实外星器官或失控异形身体。', defEn: 'First read: a humanoid model alienated by runway aesthetics, not a monster. Styling entry: a humanoid model alienated by runway aesthetics, not a monster. Motif: couture turning the face into an alien interface. Tension: nonhuman feeling must come from fashion language while the body remains a readable human model base. Visual evidence: pale makeup, elongated eyes, sculptural clothing, mechanical walk, and material reflection. Boundary: avoid generate real alien organs or uncontrolled creature anatomy.', ontologyLevel: 2, eras: contemporaryEras, risk: 'medium', tags: ['avant_garde', 'alien_makeup', 'runway'] },
  { id: 'east_europe_cold_model', name: '东欧冷脸模特', nameEn: 'Eastern European Cold-Face Model', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是国际秀场体系里的东欧冷脸模特：高颧骨、冷淡眼神和纤长身形形成硬质美感。造型入口：国际秀场体系里的东欧冷脸模特：高颧骨、冷淡眼神和纤长身形形成硬质美感。母题：长期在机场、后台和秀场间迁徙的职业身体。张力：年轻外表与过度职业化疲惫并存。视觉证据：黑色后台外套、极简长裤、冷色高定、眼下疲劳和难以接近的站姿。边界：避免写成民族标签或普通冰山美人。', defEn: 'First read: an Eastern European cold-face model inside the international runway system, with high cheekbones, cold gaze, and elongated frame. Styling entry: an Eastern European cold-face model inside the international runway system, with high cheekbones, cold gaze, and elongated frame. Motif: a professional body migrating between airports, backstage corridors, and shows. Tension: youth mixed with over-professional fatigue. Visual evidence: black backstage coat, minimal trousers, cool-toned couture, under-eye tiredness, and inaccessible posture. Boundary: avoid turn it into an ethnicity label or generic icy beauty.', tags: ['model', 'cold_face', 'backstage'] },
  { id: 'androgynous_couture_model', name: '中性高定模特', nameEn: 'Androgynous Couture Model', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是性别边界被高定剪裁压低的模特。造型入口：性别边界被高定剪裁压低的模特。母题：“不可分类的秀场身体”。张力：性别线索被减少，但骨相、肩线和站姿反而变得更有压迫力。视觉证据：平直身体线、极简高领、窄肩或硬肩结构、克制妆发和冷静正面性。边界：避免用夸张性别符号解释，也不要变成单纯中性漂亮。', defEn: 'First read: a model whose gender boundary is lowered by couture cut. Styling entry: a model whose gender boundary is lowered by couture cut. Motif: the unclassifiable runway body. Tension: gender cues are reduced while bone structure, shoulder line, and stance become more forceful. Visual evidence: straight body line, minimal high collar, narrow or hard shoulders, restrained hair/makeup, and calm frontality. Boundary: avoid explain it through exaggerated gender signs or reduce it to neutral prettiness.', tags: ['androgynous', 'couture', 'model'] },
  { id: 'haute_couture_bride', name: '高定新娘', nameEn: 'Haute Couture Bride', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是被展示出来的高定婚礼神话，不是生活里的普通新娘。造型入口：被展示出来的高定婚礼神话，不是生活里的普通新娘。母题：白色仪式中心。张力：纯洁感被制造得极其精确，因而带有距离和压迫。视觉证据：压轴婚纱、长面纱、白色刺绣、极慢步伐和被期待固定住的脸。边界：避免写成甜美婚纱写真或普通恋爱角色。', defEn: 'First read: a displayed couture bridal myth, not an ordinary bride from daily life. Styling entry: a displayed couture bridal myth, not an ordinary bride from daily life. Motif: the white ritual center. Tension: purity is manufactured so precisely it becomes distant and pressuring. Visual evidence: finale bridal gown, long veil, white embroidery, extremely slow movement, and a face fixed by expectation. Boundary: avoid making it a sweet wedding shoot or generic romance character.', tags: ['bridal', 'veil', 'couture'] },
  { id: 'black_couture_widow', name: '黑色高定寡妇', nameEn: 'Black Couture Widow', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是把哀悼训练成公共优雅的黑色高定寡妇。造型入口：把哀悼训练成公共优雅的黑色高定寡妇。母题：遗产、丧礼和上流社交交叠的女性身体。张力：真实悲伤被礼仪和阶层压成冷静表情。视觉证据：黑色礼服、薄面纱、冷光珠宝、遮蔽皮肤和有重量的站姿。边界：避免写成恐怖寡妇或单纯哥特美人。', defEn: 'First read: a black couture widow who has trained mourning into public elegance. Styling entry: a black couture widow who has trained mourning into public elegance. Motif: a female body where inheritance, funeral ritual, and high society overlap. Tension: real grief compressed by etiquette and class into a calm face. Visual evidence: black gown, sheer veil, cold jewelry, concealed skin, and weighted posture. Boundary: avoid making her a horror widow or merely a goth beauty.', tags: ['black_couture', 'widow', 'mourning'] },
  { id: 'architectural_shoulder_model', name: '建筑肩线模特', nameEn: 'Architectural-Shoulder Model', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是肩部结构先于面孔出现的高定模特。造型入口：方肩、雕塑肩和被服装重新规定的手臂距离。母题：身体被服装改造成建筑立面。张力：情绪被压低，权力却从比例重写中放大。视觉证据：方肩、雕塑肩、硬壳胸衣、肩颈留白、中轴稳定站姿和被服装重新规定的手臂距离。边界：避免把夸张肩线变成战甲或怪物骨骼。', defEn: 'First read: a couture model whose shoulder structure arrives before the face. Styling entry: square shoulders, sculptural shoulders, and arm distance newly dictated by the garment. Motif: a body turned by clothing into an architectural facade. Tension: emotion is reduced while power grows through rewritten proportion. Visual evidence: square shoulders, sculptural shoulders, hard bodice, neck-shoulder negative space, central-axis stillness, and arm distance newly dictated by the garment. Boundary: avoid turning the shoulders into armor or monster bones.', tags: ['architectural', 'shoulder', 'silhouette'] },
  { id: 'couture_fitting_girl', name: '高定试衣女孩', nameEn: 'Couture Fitting Girl', group: 'A. 高定秀场人物', groupEn: 'A. Couture Runway Figures', def: '第一识别是处在成品之前、正在被工坊调整的高定试衣身体。造型入口：处在成品之前、正在被工坊调整的高定试衣身体。母题：服装诞生过程中的临时模特。张力：她既专业配合，又显出疲惫和脆弱。视觉证据：半完成礼服、别针、白棉试衣布、粉笔线、被要求保持不动的姿态。边界：避免写成成品大片或普通灰姑娘变装。', defEn: 'First read: a couture fitting body being adjusted by the atelier before the garment is finished. Styling entry: a couture fitting body being adjusted by the atelier before the garment is finished. Motif: the temporary model inside garment birth. Tension: professional cooperation mixed with fatigue and vulnerability. Visual evidence: half-made gown, pins, white toile, chalk lines, and a posture asked to stay still. Boundary: avoid turn it into a finished campaign image or generic makeover fantasy.', tags: ['fitting', 'toile', 'atelier'] },

  { id: 'oscar_best_actress', name: '奥斯卡影后', nameEn: 'Oscar Best Actress', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是刚获得最高奖项、正在被闪光灯固定的影后。造型入口：刚获得最高奖项、正在被闪光灯固定的影后。母题：胜利后的公共身体。张力：荣耀很亮，情绪却必须被训练成可观看、不可失控。视觉证据：奖杯、定制礼服、珠宝、精确妆发、微微收紧的肩颈和含泪但稳住的表情。边界：避免写成普通红毯女星或夸张哭戏。', defEn: 'First read: a best-actress winner fixed by flashbulbs just after receiving the highest award. Styling entry: a best-actress winner fixed by flashbulbs just after receiving the highest award. Motif: the public body after victory. Tension: glory is bright while emotion must be trained into something watchable and controlled. Visual evidence: trophy, custom gown, jewelry, precise hair/makeup, slightly tightened neck-shoulder line, and tearful but steady expression. Boundary: avoid making her a generic red-carpet actress or melodramatic crying scene.', tags: ['red_carpet', 'actress', 'award'] },
  { id: 'cannes_film_muse', name: '戛纳电影节缪斯', nameEn: 'Cannes Film Festival Muse', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是海滨电影节台阶上的艺术片缪斯。造型入口：海滨电影节台阶上的艺术片缪斯。母题：导演、摄影记者和电影节神话共同制造的远距离幻象。张力：她看似慵懒，却被所有镜头严密塑造。视觉证据：强烈海边光、墨镜、被风吹起的礼服裙摆、红毯台阶和骄傲但不可触碰的姿态。边界：避免写成普通度假明星或商业红毯模板。', defEn: 'First read: an art-film muse on seaside festival stairs. Styling entry: an art-film muse on seaside festival stairs. Motif: a distant illusion made by directors, press photographers, and festival mythology. Tension: she appears lazy while every camera tightly constructs her. Visual evidence: hard seaside light, sunglasses, wind-lifted gown hem, red-carpet stairs, and a proud inaccessible posture. Boundary: avoid turn her into a generic vacation celebrity or commercial red-carpet template.', tags: ['cannes', 'film_festival', 'muse'] },
  { id: 'met_gala_surreal_socialite', name: 'Met Gala怪诞名流', nameEn: 'Met Gala Surreal Socialite', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是把主题红毯当作社交战场的怪诞名流。造型入口：把主题红毯当作社交战场的怪诞名流。母题：由公关、造型师和媒体时机共同制造的高级奇观。张力：造型可以荒诞，但本人必须仍然懂得阶层和镜头规则。视觉证据：夸张头饰、礼服体块、超现实符号、精确站位和自知的社交微笑。边界：避免写成随机怪物装或失控Cosplay。', defEn: 'First read: a surreal socialite treating the themed red carpet as a social battlefield. Styling entry: a surreal socialite treating the themed red carpet as a social battlefield. Motif: a high spectacle produced by PR, styling, and media timing. Tension: the look may be absurd while the person still understands class and camera rules. Visual evidence: exaggerated headpiece, gown volume, surreal signs, precise placement, and a self-aware social smile. Boundary: avoid making it random monster costume or uncontrolled cosplay.', ontologyLevel: 2, risk: 'medium', tags: ['met_gala', 'surreal', 'socialite'] },
  { id: 'pop_diva_red_carpet', name: '流行天后红毯造型', nameEn: 'Pop Diva Red Carpet Look', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是把舞台控制力带上红毯的流行天后。造型入口：把舞台控制力带上红毯的流行天后。母题：被安保、镜头和粉丝凝视围绕的明星中心。张力：她看似亲近公众，却用每个角度维持不可接近。视觉证据：闪钻礼服、长发、贴身剪裁、保镖距离、排练过的身体角度和服务明星权力的微笑手势。边界：避免写成普通歌手或亲民街拍。', defEn: 'First read: a pop diva bringing stage command onto the red carpet. Styling entry: a pop diva bringing stage command onto the red carpet. Motif: a star center surrounded by guards, cameras, and fan gaze. Tension: she appears public-facing while every angle maintains inaccessibility. Visual evidence: crystal gown, long hair, body-hugging cut, guarded distance, rehearsed body angle, and smile/gesture serving star power. Boundary: avoid making her a generic singer or approachable street snap.', tags: ['pop_diva', 'red_carpet', 'celebrity'] },
  { id: 'red_carpet_scandal_star', name: '红毯绯闻女星', nameEn: 'Red Carpet Scandal Star', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是把绯闻变成红毯资产的争议女星。造型入口：把绯闻变成红毯资产的争议女星。母题：舆论事件中的公共身体。张力：她一半防御媒体围堵，一半主动利用镜头扩散自己。视觉证据：争议礼服、闪躲微笑、过度精准的曝光度、媒体包围感和带计算的站姿。边界：避免写成狼狈受害者或纯负面八卦人物。', defEn: 'First read: a controversial actress turning scandal into red-carpet capital. Styling entry: a controversial actress turning scandal into red-carpet capital. Motif: the public body inside a media incident. Tension: she is half defending against the press and half using cameras to amplify herself. Visual evidence: controversial gown, evasive smile, precisely managed exposure, press crowding, and calculated stance. Boundary: avoid making her merely a cornered victim or pure gossip figure.', risk: 'medium', tags: ['scandal', 'celebrity', 'media'] },
  { id: 'venice_old_hollywood_star', name: '威尼斯老 Hollywood 女星', nameEn: 'Venice Old-Hollywood Star', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是带着威尼斯慢光和旧明星制度残影的红毯女星。造型入口：带着威尼斯慢光和旧明星制度残影的红毯女星。母题：尚未退场的老Hollywood幻象。张力：她身处现代电影节，却用过时的距离感压住现场。视觉证据：复古波浪发、丝缎礼服、红唇、小手势、稳定眼神和不完全给人的笑容。边界：避免写成普通复古装扮或华丽堆饰。', defEn: 'First read: a red-carpet actress carrying Venice’s slow light and the residue of the old star system. Styling entry: a red-carpet actress carrying Venice’s slow light and the residue of the old star system. Motif: an Old-Hollywood illusion that has not fully exited. Tension: she stands in a modern festival while controlling it through old-fashioned distance. Visual evidence: vintage waves, satin gown, red lips, small gestures, steady gaze, and a smile never fully given. Boundary: avoid making it generic retro styling or decorative glamour.', tags: ['venice', 'old_hollywood', 'satin'] },
  { id: 'red_carpet_method_actor', name: '方法派红毯演员', nameEn: 'Method Actor on Red Carpet', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是还没有完全从角色里退出的方法派演员。造型入口：还没有完全从角色里退出的方法派演员。母题：宣传期红毯上的表演残留。张力：他必须作为明星亮相，身体却仍被上一段角色和职业耗损占据。视觉证据：克制礼服或西装、沉默眼神、宣传疲惫、微迟钝反应和不像摆拍的站姿。边界：避免写成华丽偶像或角色本身。', defEn: 'First read: a method actor not fully out of the role. Styling entry: a method actor not fully out of the role. Motif: performance residue on a press-tour red carpet. Tension: he must appear as a star while the body is still occupied by the role and professional wear. Visual evidence: restrained gown or suit, silent gaze, press fatigue, slight delayed reaction, and a stance that does not feel posed. Boundary: avoid making him a glamorous idol or the fictional role itself.', tags: ['actor', 'method', 'press_tour'] },
  { id: 'fashion_week_front_row_star', name: '时装周前排明星', nameEn: 'Fashion Week Front-Row Star', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是坐在时装周前排、不是走秀却同样被观看的明星。造型入口：坐在时装周前排、不是走秀却同样被观看的明星。母题：座位权力和品牌借衣共同制造的时尚可见性。张力：她看似旁观，实际也是秀的一部分。视觉证据：墨镜、交叠双腿、刚从品牌陈列取出的造型、低声社交和故意不看镜头的姿态。边界：避免写成普通观众或秀场模特。', defEn: 'First read: a fashion-week front-row star, not walking the show yet still being watched. Styling entry: a fashion-week front-row star, not walking the show yet still being watched. Motif: fashion visibility produced by seating power and borrowed brand looks. Tension: she appears to observe while actually being part of the show. Visual evidence: sunglasses, crossed legs, showroom-fresh styling, low social murmurs, and deliberately not looking at the camera. Boundary: avoid making her a normal audience member or runway model.', tags: ['front_row', 'fashion_week', 'celebrity'] },
  { id: 'red_carpet_pregnancy_reveal', name: '红毯孕肚公开明星', nameEn: 'Red Carpet Pregnancy Reveal Star', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是把身体变化转化为可控公开事件的红毯明星。造型入口：把身体变化转化为可控公开事件的红毯明星。母题：被媒体见证的成人公共身体。张力：柔软私人状态被安排成精准的明星叙事。视觉证据：贴身礼服、手扶腹部、保护性手势、柔软表情、剪裁支撑和闪光灯见证。边界：保持尊重，避免露骨化、医疗化或写成家庭故事。', defEn: 'First read: a red-carpet star turning bodily change into a controlled public reveal. Styling entry: a red-carpet star turning bodily change into a controlled public reveal. Motif: an adult public body witnessed by media. Tension: a soft private state is arranged into precise celebrity narrative. Visual evidence: body-hugging gown, hand on belly, protective gesture, soft expression, supportive cut, and flashbulb witnessing. Boundary: keep it respectful; avoid sexualized, medicalized, or turned into family story.', risk: 'medium', tags: ['red_carpet', 'body_narrative', 'celebrity'] },
  { id: 'red_carpet_comeback_icon', name: '红毯复出偶像', nameEn: 'Red Carpet Comeback Icon', group: 'B. 红毯 / 明星礼服', groupEn: 'B. Red Carpet / Celebrity Gowns', def: '第一识别是重新进入观看系统的复出偶像。造型入口：重新进入观看系统的复出偶像。母题：被媒体等待的回归仪式。张力：造型必须完美，但眼神仍暴露出曾经消失后的压力。视觉证据：不吵的高级礼服、克制泪光、硬撑的平静、重新校准的站姿和过度精确的妆发。边界：避免写成普通红毯亮相或励志剧情。', defEn: 'First read: a comeback icon re-entering the system of being watched. Styling entry: a comeback icon re-entering the system of being watched. Motif: a return ritual waited for by media. Tension: styling must be perfect while the eyes still reveal pressure after disappearance. Visual evidence: quiet high-end gown, restrained tears, hard-won calm, recalibrated posture, and overly precise hair/makeup. Boundary: avoid turn it into a generic red-carpet appearance or inspirational plot.', tags: ['comeback', 'icon', 'red_carpet'] },

  { id: 'fashion_editor_in_chief', name: '时尚杂志主编', nameEn: 'Fashion Magazine Editor-in-Chief', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是能用沉默完成审美裁决的杂志主编。造型入口：能用沉默完成审美裁决的杂志主编。母题：图像工业里的最高观看者。张力：她身体极少动作，却让封面、模特和品牌命运围着她转。视觉证据：短发或墨镜、黑色套装、前排座位、文件夹、团队环绕和不急于表达的脸。边界：避免写成普通女强人或大声命令的老板。', defEn: 'First read: a magazine editor-in-chief who can make aesthetic judgments through silence. Styling entry: a magazine editor-in-chief who can make aesthetic judgments through silence. Motif: the highest viewer inside the image industry. Tension: her body moves very little while covers, models, and brand fates orbit her. Visual evidence: bob or sunglasses, black suit, front-row seat, folders, surrounding staff, and a face in no hurry to explain. Boundary: avoid making her a generic powerful woman or loud boss.', tags: ['editor', 'magazine', 'authority'] },
  { id: 'cold_editorial_stylist', name: '冷感造型编辑', nameEn: 'Cold Editorial Stylist', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是拍摄现场里冷静、挑剔、直接改写身体形象的造型编辑。造型入口：拍摄现场里冷静、挑剔、直接改写身体形象的造型编辑。母题：把服装、模特和照片整理成一个审美方向的人。张力：她靠手部小动作控制全场，而不是自己成为明星。视觉证据：黑衣、夹子、样衣架、材质对照、贴近模特衣领的手和审视式眼神。边界：避免写成普通穿搭博主或被拍摄对象。', defEn: 'First read: a cool, critical editorial stylist on set, directly rewriting bodily image. Styling entry: a cool, critical editorial stylist on set, directly rewriting bodily image. Motif: someone who organizes clothing, model, and photograph into one aesthetic direction. Tension: small hand movements control the room while she herself is not the star. Visual evidence: black clothing, clips, sample racks, material comparisons, hands near a model collar, and an inspecting gaze. Boundary: avoid making her a fashion blogger or the subject being photographed.', tags: ['stylist', 'editorial', 'shoot'] },
  { id: 'cover_girl', name: '杂志封面女郎', nameEn: 'Magazine Cover Girl', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是已经被想象成封面版面的明星面孔。造型入口：已经被想象成封面版面的明星面孔。母题：可印刷、可标题化、可被市场记住的图像身体。张力：她看似自然出现，其实每个角度都为封面服务。视觉证据：强记忆表情、干净但锋利的妆发、适合被文字包围的轮廓、正面凝视和可留白的姿态。边界：避免写成生活化美女或普通拍照模特。', defEn: 'First read: a star face already imagined as a magazine cover layout. Styling entry: a star face already imagined as a magazine cover layout. Motif: a printable, headline-ready, market-memorable image body. Tension: she seems natural while every angle serves the cover. Visual evidence: a memorable expression, clean but sharp hair and makeup, a silhouette ready for text around it, frontal gaze, and a posture with graphic negative space. Boundary: avoid making her a daily-life beauty or generic photo model.', tags: ['cover_girl', 'magazine', 'print'] },
  { id: 'fashion_photography_assistant', name: '时尚摄影助理', nameEn: 'Fashion Photography Assistant', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是时尚大片背后负责让画面成立的现场劳动者。造型入口：时尚大片背后负责让画面成立的现场劳动者。母题：图像生产链里不被看见的执行身体。张力：她不站中心，却用工具、速度和判断支撑中心。视觉证据：黑色工作服、胶带、反光板、器材包、跑动姿态、被现场磨旧的鞋和随时腾出的手。边界：避免写成摄影师本人或漂亮后台模特。', defEn: 'First read: an on-set worker who makes the fashion image possible from behind it. Styling entry: an on-set worker who makes the fashion image possible from behind it. Motif: an execution body inside the unseen image-production chain. Tension: she is not center frame but supports the center through tools, speed, and judgment. Visual evidence: black workwear, tape, reflector, gear bag, running posture, set-worn shoes, and hands kept free for tasks. Boundary: avoid making her the photographer or a pretty backstage model.', tags: ['assistant', 'photo_set', 'labor'] },
  { id: 'fashion_pr_director', name: '时尚公关总监', nameEn: 'Fashion PR Director', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是把危机、宾客和媒体角度同时压住的时尚公关总监。造型入口：把危机、宾客和媒体角度同时压住的时尚公关总监。母题：礼貌外壳下的现场控制系统。张力：她必须持续微笑，同时身体已经在计算事故、席位和曝光。视觉证据：手机、嘉宾名单、耳机、黑色礼服或利落套装、不掉线的表情和半转身指挥姿态。边界：避免写成普通活动主持或品牌销售。', defEn: 'First read: a fashion PR director holding crisis, guests, and media angles in place at once. Styling entry: a fashion PR director holding crisis, guests, and media angles in place at once. Motif: a live control system under a polite shell. Tension: she must keep smiling while her body calculates problems, seating, and exposure. Visual evidence: phone, guest list, earpiece, black formal look or sharp suit, an unbroken expression, and half-turned directing posture. Boundary: avoid making her an event host or brand salesperson.', tags: ['pr', 'director', 'event'] },
  { id: 'beauty_editor', name: '美妆编辑', nameEn: 'Beauty Editor', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是把脸、肤质和色号当作编辑对象的美妆编辑。造型入口：把脸、肤质和色号当作编辑对象的美妆编辑。母题：近距离判断颜色与商业可读性的专业观看者。张力：她自己可以很干净，但眼睛极其苛刻。视觉证据：口红试色、手背色块、产品包、精确妆面、微微前倾观察和关注皮肤细节的姿态。边界：避免写成浓妆网红或化妆师职业照。', defEn: 'First read: a beauty editor who treats face, skin texture, and shade as editorial material. Styling entry: a beauty editor who treats face, skin texture, and shade as editorial material. Motif: a close-range professional viewer judging color and commercial readability. Tension: she may look clean herself while her eye is extremely demanding. Visual evidence: lipstick swatches, shade marks on the hand, product bag, precise makeup, slight forward lean, and posture focused on skin detail. Boundary: avoid making her a heavy-makeup influencer or makeup-artist work portrait.', tags: ['beauty', 'editor', 'makeup'] },
  { id: 'street_style_photographer', name: '街拍摄影师', nameEn: 'Street Style Photographer', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是时装周街角捕捉造型的街拍摄影师。造型入口：时装周街角捕捉造型的街拍摄影师。母题：把城市人群过滤成可发表图像的移动观看者。张力：他穿得实用，却带着编辑部式的审美嗅觉。视觉证据：相机、长外套、快速步伐、前倾身体、寻找衣服的人群视线和略有品味的功能穿搭。边界：避免写成旅游摄影师或普通潮人。', defEn: 'First read: a street-style photographer capturing looks on fashion-week corners. Styling entry: a street-style photographer capturing looks on fashion-week corners. Motif: a moving viewer who filters city crowds into publishable images. Tension: practical dress mixed with an editorial sense of taste. Visual evidence: camera, long coat, fast steps, forward-leaning body, eyes scanning crowds for clothing, and functional styling with a trace of taste. Boundary: avoid making him a tourist photographer or generic fashionable passerby.', tags: ['street_style', 'photographer', 'fashion_week'] },
  { id: 'casting_director', name: '模特选角总监', nameEn: 'Model Casting Director', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是用几秒钟判断身体价值的模特选角总监。造型入口：用几秒钟判断身体价值的模特选角总监。母题：白墙试镜里的冷静裁决者。张力：他造型不夸张，却让排队等待的人都变成被评估材料。视觉证据：资料夹、白墙、坐姿、抬眼瞬间、笔、平板和不会安慰人的表情。边界：避免写成普通经纪人或华丽时尚人物。', defEn: 'First read: a model casting director who judges bodily value within seconds. Styling entry: a model casting director who judges bodily value within seconds. Motif: the calm arbiter inside a white-wall casting. Tension: his styling is not dramatic, yet everyone waiting becomes evaluated material. Visual evidence: folders, white wall, seated posture, lifted-eye moment, pen, tablet, and an expression that does not comfort. Boundary: avoid making him a generic agent or glamorous fashion figure.', tags: ['casting', 'model', 'authority'] },
  { id: 'fashion_archive_keeper', name: '时装档案管理员', nameEn: 'Fashion Archive Keeper', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是像照看时间一样照看衣服的时装档案管理员。造型入口：像照看时间一样照看衣服的时装档案管理员。母题：保存制度里的安静权威。张力：她本人必须低调退后，让历史织物、标签和保护流程成为主角。视觉证据：白手套、旧高定、衣袋标签、档案室冷光、缓慢手势和谨慎眼神。边界：避免写成复古贵妇或普通仓库管理员。', defEn: 'First read: a fashion archive keeper who cares for garments as if caring for time. Styling entry: a fashion archive keeper who cares for garments as if caring for time. Motif: quiet authority inside preservation systems. Tension: she must recede so historical textiles, tags, and protection processes become central. Visual evidence: white gloves, old couture, garment tags, cold archive light, slow gestures, and careful eyes. Boundary: avoid making her a retro aristocrat or generic warehouse clerk.', tags: ['archive', 'keeper', 'heritage'] },
  { id: 'fashion_critic', name: '尖刻时评人', nameEn: 'Sharp Fashion Critic', group: 'C. 时尚杂志系统', groupEn: 'C. Fashion Magazine System', def: '第一识别是靠观看和语言制造压力的尖刻时评人。造型入口：靠观看和语言制造压力的尖刻时评人。母题：前排座位上的审判身体。张力：他外形克制，存在感却像一把坐着的刀。视觉证据：笔记本、冷笑、黑色窄身造型、不急着鼓掌的手、斜向观察和拒绝被秀场取悦的姿态。边界：避免写成搞笑毒舌角色或普通观众。', defEn: 'First read: a sharp fashion critic who creates pressure through looking and language. Styling entry: a sharp fashion critic who creates pressure through looking and language. Motif: a judging body in the front row. Tension: his appearance is restrained while his presence feels like a seated blade. Visual evidence: notebook, dry smile, narrow black styling, hands that do not rush to applaud, angled observation, and posture refusing to be pleased by the show. Boundary: avoid making him a comic insult character or normal audience member.', tags: ['critic', 'front_row', 'judgment'] },

  { id: 'chanel_socialite', name: '香奈儿名媛', nameEn: 'Chanel Socialite', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是把经典上流克制穿成日常制服的虚构奢侈名媛。造型入口：把经典上流克制穿成日常制服的虚构奢侈名媛。母题：被礼仪和品牌语法长期训练过的社交身体。张力：她看似柔和礼貌，实际用距离感维持阶层边界。视觉证据：粗花呢套装、珍珠、菱格纹包感、山茶花式配饰、挺直背部和小幅度手势。边界：避免使用真实logo，也不要写成普通富家女孩。', defEn: 'First read: a fictional luxury socialite wearing classic upper-class restraint as a daily uniform. Styling entry: a fictional luxury socialite wearing classic upper-class restraint as a daily uniform. Motif: a social body trained for years by etiquette and brand grammar. Tension: she appears soft and polite while using distance to maintain class borders. Visual evidence: tweed suit, pearls, quilted-bag feeling, camellia-like accessory, straight back, and small gestures. Boundary: avoid use real logos or make her a generic rich girl.', tags: ['chanel', 'tweed', 'socialite'] },
  { id: 'dior_princess', name: '迪奥公主', nameEn: 'Dior Princess', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是被花朵、腰线和柔光保护起来的浪漫高定公主。造型入口：被花朵、腰线和柔光保护起来的浪漫高定公主。母题：温室式贵族少女。张力：甜美必须被工艺和阶层距离托住，不能滑向廉价可爱。视觉证据：花朵刺绣、收腰大裙、柔软妆面、被呵护出的慢动作和不直接接近人的眼神。边界：避免写成童话公主或普通甜妹礼服。', defEn: 'First read: a romantic couture princess protected by flowers, waistline, and soft light. Styling entry: a romantic couture princess protected by flowers, waistline, and soft light. Motif: a greenhouse aristocratic girl. Tension: sweetness must be held by craft and class distance, never cheap cuteness. Visual evidence: floral embroidery, cinched full skirt, soft makeup, sheltered slow movement, and eyes that do not fully invite approach. Boundary: avoid making her a fairy-tale princess or generic sweet gown girl.', tags: ['dior', 'princess', 'romantic'] },
  { id: 'gucci_geek_heir', name: '古驰怪咖继承人', nameEn: 'Gucci Geek Heir', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是把书呆子怪趣味穿成继承资产的奢侈怪咖。造型入口：把书呆子怪趣味穿成继承资产的奢侈怪咖。母题：旧书、奇怪家具和过量图案里长大的富家继承人。张力：品味故意不协调，却明显有钱、有知识、有收藏癖支撑。视觉证据：复古大眼镜、撞色图案、丰盛层次、怪异配饰和自信到不解释的站姿。边界：避免写成普通宅男宅女或随机花哨潮人。', defEn: 'First read: a luxury eccentric wearing nerdy weird taste as inherited capital. Styling entry: a luxury eccentric wearing nerdy weird taste as inherited capital. Motif: a wealthy heir raised among old books, strange furniture, and excessive pattern. Tension: deliberate mismatch supported by money, knowledge, and collecting instinct. Visual evidence: oversized vintage glasses, clashing patterns, abundant layers, odd accessories, and a posture confident enough not to explain. Boundary: avoid making a generic nerd or random flashy street dresser.', tags: ['gucci', 'geek', 'eccentric'] },
  { id: 'balenciaga_dystopian_model', name: '巴黎世家末世模特', nameEn: 'Balenciaga Dystopian Model', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是被奢侈工业包装成末世废墟感的巨型廓形模特。造型入口：被奢侈工业包装成末世废墟感的巨型廓形模特。母题：商业化灾难美学里的空脸身体。张力：她像幸存者，却没有真正求生的脏乱，只剩昂贵、沉重、压低人的造型压力。视觉证据：巨大外套、泥地秀场感、空表情、厚重鞋、身体被衣服吞下的比例。边界：避免写成真实灾民或科幻战士。', defEn: 'First read: an oversized-silhouette model packaged by luxury industry as dystopian ruin. Styling entry: an oversized-silhouette model packaged by luxury industry as dystopian ruin. Motif: a blank-faced body inside commercial disaster aesthetics. Tension: she resembles a survivor without real survival dirt, leaving only expensive, heavy, body-suppressing styling pressure. Visual evidence: enormous outerwear, mud-runway feeling, empty expression, heavy shoes, and a proportion swallowed by clothing. Boundary: avoid making a real disaster victim or sci-fi soldier.', ontologyLevel: 2, risk: 'medium', tags: ['balenciaga', 'dystopian', 'oversized'] },
  { id: 'rick_owens_cultist', name: 'Rick Owens黑袍信徒', nameEn: 'Rick Owens Black-Robed Devotee', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是把黑色垂坠和身体纪律穿成地下仪式的人。造型入口：把黑色垂坠和身体纪律穿成地下仪式的人。母题：健身房、神殿和秀场混合出的严肃时装信徒。张力：他像异教成员，却所有神秘感都来自比例、肌肉控制和布料重量。视觉证据：黑色层叠、厚底靴、苍白皮肤、长线条、低头姿态和雕塑般身体秩序。边界：避免写成普通哥特或真正宗教角色。', defEn: 'First read: a figure wearing black drape and body discipline as underground ritual. Styling entry: a figure wearing black drape and body discipline as underground ritual. Motif: a severe fashion devotee born from gym, temple, and runway at once. Tension: cult-like presence whose mystery comes only from proportion, muscle control, and textile weight. Visual evidence: black layers, platform boots, pale skin, long lines, lowered head, and sculptural bodily order. Boundary: avoid making ordinary goth or a real religious figure.', ontologyLevel: 2, risk: 'medium', tags: ['rick_owens', 'black_layers', 'cult'] },
  { id: 'mcqueen_savage_muse', name: '麦昆野性缪斯', nameEn: 'McQueen Savage Muse', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是介于美、受伤和攻击性之间的野性高定缪斯。造型入口：介于美、受伤和攻击性之间的野性高定缪斯。母题：被自然残酷美和精密工艺共同制成的活标本。张力：她可以带动物性和危险感，但必须始终保持高定精度。视觉证据：羽毛、骨感配饰、尖锐廓形、脆弱眼神、戏剧姿态和像伤口一样精确的剪裁。边界：避免写成野兽女孩或普通暗黑模特。', defEn: 'First read: a savage couture muse between beauty, injury, and aggression. Styling entry: a savage couture muse between beauty, injury, and aggression. Motif: a living specimen produced by cruel nature and exact craft together. Tension: animality and danger are allowed only while couture precision remains intact. Visual evidence: feathers, bone-like accessories, sharp silhouette, vulnerable eyes, dramatic posture, and cuts as precise as wounds. Boundary: avoid making her a beast girl or generic dark model.', ontologyLevel: 2, risk: 'medium', tags: ['mcqueen', 'savage', 'muse'] },
  { id: 'prada_intellectual', name: '普拉达知性怪人', nameEn: 'Prada Intellectual Oddball', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是故意拒绝讨好性感的知性时装怪人。造型入口：故意拒绝讨好性感的知性时装怪人。母题：聪明、别扭、克制的反漂亮身体。张力：她看似不追求好看，却通过比例、尼龙材质和冷静态度显得更高级。视觉证据：实用包、尼龙、丑美学配色、平静表情、略硬的站姿和不解释的知识分子气。边界：避免写成普通办公室知性或随便穿错衣服。', defEn: 'First read: an intellectual fashion oddball deliberately refusing pleasing sexiness. Styling entry: an intellectual fashion oddball deliberately refusing pleasing sexiness. Motif: a smart, awkward, restrained anti-pretty body. Tension: she seems not to seek beauty but becomes refined through proportion, nylon material, and calm attitude. Visual evidence: practical bag, nylon, ugly-chic palette, quiet face, slightly stiff stance, and unexplained intellectual air. Boundary: avoid making a generic office intellectual or accidental bad dresser.', tags: ['prada', 'intellectual', 'nylon'] },
  { id: 'margiela_masked_model', name: 'Margiela面具模特', nameEn: 'Margiela Masked Model', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是脸被撤走、服装结构被推到前台的匿名模特。造型入口：脸被撤走、服装结构被推到前台的匿名模特。母题：身份退场后的解构载体。张力：角色不靠五官成立，而靠轮廓、线迹和被消隐的自我感成立。视觉证据：遮脸面具、白色线迹、反穿衣片、标签残影、空白姿态和不寻求表情的身体。边界：避免写成怪物面具或神秘刺客。', defEn: 'First read: an anonymous model whose face is removed so garment structure steps forward. Styling entry: an anonymous model whose face is removed so garment structure steps forward. Motif: a deconstructed carrier after identity exits. Tension: the character cannot rely on features, only on silhouette, stitches, and erased selfhood. Visual evidence: face covering, white stitches, inside-out garment pieces, label residue, blank posture, and a body not seeking expression. Boundary: avoid making a monster mask or mysterious assassin.', ontologyLevel: 2, risk: 'medium', tags: ['margiela', 'mask', 'deconstruction'] },
  { id: 'vivienne_westwood_punk_aristocrat', name: '西太后朋克贵族', nameEn: 'Vivienne Westwood Punk Aristocrat', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是懂礼仪却故意拆礼仪的英伦朋克贵族。造型入口：懂礼仪却故意拆礼仪的英伦朋克贵族。母题：把王室残影、束身衣和街头叛逆拧在一起的反传统身体。张力：她既有阶层遗产，又把遗产穿成挑衅。视觉证据：格纹、束身衣、珍珠、歪斜王冠、裙撑、破坏性配饰和挑衅站姿。边界：避免写成普通朋克女孩或规整宫廷贵族。', defEn: 'First read: a British punk aristocrat who knows etiquette and deliberately breaks it. Styling entry: a British punk aristocrat who knows etiquette and deliberately breaks it. Motif: an anti-tradition body twisting royal residue, corsetry, and street rebellion together. Tension: she has class inheritance but wears it as provocation. Visual evidence: tartan, corset, pearls, tilted crown, crinoline, destructive accessories, and challenging stance. Boundary: avoid making a generic punk girl or proper court noble.', tags: ['westwood', 'punk', 'aristocrat'] },
  { id: 'schiaparelli_surreal_muse', name: 'Schiaparelli超现实缪斯', nameEn: 'Schiaparelli Surreal Muse', group: 'D. 奢侈品牌人格', groupEn: 'D. Luxury Brand Personas', def: '第一识别是把梦境符号穿成高级珠宝的超现实缪斯。造型入口：把梦境符号穿成高级珠宝的超现实缪斯。母题：优雅礼服表面长出荒诞视觉谜题的人。张力：异常必须昂贵、清晰、可控，不能滑成怪物身体。视觉证据：金色身体部件珠宝、眼睛符号、黑丝绒、静止表情和像谜语一样贴在衣服上的装饰。边界：避免生成真实异形器官。', defEn: 'First read: a surreal muse wearing dream symbols as high jewelry. Styling entry: a surreal muse wearing dream symbols as high jewelry. Motif: a person whose elegant gown surface carries absurd visual riddles. Tension: abnormality must stay expensive, clear, and controlled, never becoming monster anatomy. Visual evidence: gold body-part jewelry, eye symbols, black velvet, still expression, and riddle-like decorations attached to clothing. Boundary: avoid generate real anomalous organs.', ontologyLevel: 2, risk: 'medium', tags: ['schiaparelli', 'surreal', 'gold'] },

  { id: 'victorias_secret_angel', name: '维秘超模', nameEn: 'Victoria’s Secret Angel', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是商业舞台上高饱和、成人化、广告化的性感超模。造型入口：商业舞台上高饱和、成人化、广告化的性感超模。母题：被观众、灯光和品牌共同制造的健康魅力身体。张力：她必须显得轻松自信，但身体每个角度都经过训练。视觉证据：蓬松卷发、闪粉皮肤、长线条、舞台翅膀式装饰、控制过的笑容和强走台姿态。边界：避免写成未成年甜美或普通泳装写真。', defEn: 'First read: an adult, advertising-coded supermodel of high-saturation stage glamour. Styling entry: an adult, advertising-coded supermodel of high-saturation stage glamour. Motif: a healthy allure body produced by audience, lights, and brand. Tension: she must look effortless while every angle is trained. Visual evidence: voluminous waves, glittered skin, long lines, stage-wing-like decoration, controlled smile, and powerful runway walk. Boundary: avoid making it youthful sweetness or a generic swimsuit portrait.', risk: 'medium', tags: ['victorias_secret', 'supermodel', 'commercial_glamour'] },
  { id: 'model_off_duty', name: '模特下班感', nameEn: 'Model Off-Duty', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是刚离开后台、职业比例还没有关闭的下班模特。造型入口：刚离开后台、职业比例还没有关闭的下班模特。母题：被街拍系统捕捉的非正式明星身体。张力：穿得像随便出门，却仍然像被摄影机选中。视觉证据：牛仔裤、白背心、墨镜、低调名牌包、未完全卸掉的妆发和天然拉长的站姿。边界：避免写成普通休闲女孩或过度摆拍潮人。', defEn: 'First read: an off-duty model just leaving backstage, professional proportions not fully switched off. Styling entry: an off-duty model just leaving backstage, professional proportions not fully switched off. Motif: an informal star body caught by street-snap systems. Tension: she seems casually dressed yet still looks chosen by a camera. Visual evidence: jeans, white tank, sunglasses, understated designer bag, not-fully-removed hair and makeup, and naturally elongated stance. Boundary: avoid making a normal casual girl or over-posed influencer.', tags: ['off_duty', 'model', 'street_snap'] },
  { id: 'fitness_supermodel', name: '健身超模', nameEn: 'Fitness Supermodel', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是把健身管理转化为商业美学的超模。造型入口：把健身管理转化为商业美学的超模。母题：健康产业里的可售卖身体。张力：她不是竞技运动员，却必须让自律、肌肉线和皮肤状态都显得可消费。视觉证据：运动内衣、清楚但不粗重的肌肉、营养管理痕迹、硬光自拍感、挺直核心和健康品牌式笑容。边界：避免写成健美选手或普通健身博主。', defEn: 'First read: a supermodel turning fitness management into commercial beauty. Styling entry: a supermodel turning fitness management into commercial beauty. Motif: a sellable body inside wellness industry. Tension: she is not an athlete, yet discipline, muscle lines, and skin condition must all feel marketable. Visual evidence: sports bra, clear but not heavy muscle, nutrition discipline, hard-light selfie language, strong core, and wellness-brand smile. Boundary: avoid making her a bodybuilder or generic gym influencer.', risk: 'medium', tags: ['fitness', 'supermodel', 'body_management'] },
  { id: 'new_face_model', name: '经纪公司新人模特', nameEn: 'Agency New-Face Model', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是被经纪公司当作原材料评估的新人模特。造型入口：被经纪公司当作原材料评估的新人模特。母题：明星外壳尚未生成前的潜力身体。张力：她还紧张、不完整，却已经被白墙、拍立得和行业眼光拆成可判断的比例。视觉证据：素颜、简单衣服、白墙、拍立得姿态、紧张手指和被迫正面展示的脸与身体。边界：避免写成成名超模或普通学生照。', defEn: 'First read: an agency new-face model evaluated as raw material. Styling entry: an agency new-face model evaluated as raw material. Motif: potential before the star shell forms. Tension: she is nervous and unfinished while white wall, polaroid, and industry gaze already break her into judgeable proportion. Visual evidence: bare face, simple clothing, white wall, polaroid posture, nervous fingers, and a face/body forced into frontal display. Boundary: avoid making her a famous supermodel or ordinary student portrait.', tags: ['new_face', 'agency', 'polaroid'] },
  { id: 'runway_veteran_model', name: '秀场老将模特', nameEn: 'Runway Veteran Model', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是被很多季秀场记住的老将模特。造型入口：被很多季秀场记住的老将模特。母题：行业记忆沉积在身体里的职业人。张力：她不再靠新鲜感取胜，而靠稳定台步和冷静判断压住复杂服装。视觉证据：成熟骨相、后台疲惫、极少动作、精准转身、沉默眼神和不被夸张造型扰乱的身体秩序。边界：避免写成退场明星或普通成熟美女。', defEn: 'First read: a runway veteran remembered across many seasons. Styling entry: a runway veteran remembered across many seasons. Motif: a professional body carrying industry memory. Tension: she no longer wins through novelty but through stable walk and calm judgment that controls complex garments. Visual evidence: mature facial structure, backstage fatigue, minimal movement, precise turn, silent gaze, and bodily order undisturbed by extreme styling. Boundary: avoid making her a faded star or generic mature beauty.', tags: ['veteran', 'runway', 'professional'] },
  { id: 'body_positive_model', name: '多元体型模特', nameEn: 'Body-Positive Model', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是把非样板身体稳定带入商业镜头的多元体型模特。造型入口：把非样板身体稳定带入商业镜头的多元体型模特。母题：审美范围被扩张后的广告身体。张力：她不能只是口号，必须让服装贴合、支撑和展示真实比例。视觉证据：柔软皮肤、真实曲线、稳住镜头的眼神、可靠剪裁、身体被观看时的自信和不躲避的站姿。边界：避免写成励志标语或身体羞辱。', defEn: 'First read: a body-positive model bringing a non-sample body steadily into commercial camera. Styling entry: a body-positive model bringing a non-sample body steadily into commercial camera. Motif: an advertising body after beauty standards expand. Tension: she cannot be just a slogan, clothing must genuinely fit, support, and display real proportion. Visual evidence: soft skin, real curves, gaze holding camera, reliable cut, confidence while being watched, and stance that does not hide. Boundary: avoid making an inspirational slogan or body-shaming image.', risk: 'medium', tags: ['body_positive', 'model', 'inclusive'] },
  { id: 'beauty_campaign_face', name: '美妆广告脸', nameEn: 'Beauty Campaign Face', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是能被广告近景放大的可售卖美妆脸。造型入口：能被广告近景放大的可售卖美妆脸。母题：产品、皮肤和五官秩序共同构成的商业面孔。张力：她不需要复杂身份，只要一个唇色、一个眼神和一只靠近脸的手就能成立。视觉证据：完美底妆、皮肤质感、记忆点唇色、产品手势、直视镜头和可被裁切的脸部结构。边界：避免写成普通自拍或浓妆舞台脸。', defEn: 'First read: a sellable beauty-campaign face that can be enlarged by advertising close-up. Styling entry: a sellable beauty-campaign face that can be enlarged by advertising close-up. Motif: a commercial face built by product, skin, and facial order. Tension: she needs no complex identity, only one lip color, one gaze, and one hand near the face. Visual evidence: perfected base makeup, skin texture, memorable lip color, product gesture, direct gaze, and facial structure ready for cropping. Boundary: avoid making a normal selfie or heavy stage makeup face.', tags: ['beauty_campaign', 'face', 'makeup'] },
  { id: 'luxury_fragrance_model', name: '奢侈香水广告模特', nameEn: 'Luxury Fragrance Model', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是把不可见气味拟人化的奢侈香水广告模特。造型入口：把不可见气味拟人化的奢侈香水广告模特。母题：欲望、空气感和抽象奢华凝成的身体。张力：她必须诱导观看，却不能说得太明白。视觉证据：香水瓶、裸肩礼服、湿发或风吹发、慢动作姿态、留有空气的皮肤和不可完全解释的凝视。边界：避免写成普通性感写真或产品销售员。', defEn: 'First read: a luxury fragrance model personifying an invisible scent. Styling entry: a luxury fragrance model personifying an invisible scent. Motif: a body made from desire, air, and abstract luxury. Tension: she must draw the viewer in without becoming explicit. Visual evidence: perfume bottle, bare-shoulder gown, wet or windblown hair, slow posture, skin with air around it, and a gaze that cannot be fully explained. Boundary: avoid making a generic sexy portrait or product salesperson.', risk: 'medium', tags: ['fragrance', 'luxury', 'campaign'] },
  { id: 'swimwear_campaign_model', name: '泳装大片模特', nameEn: 'Swimwear Campaign Model', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是成人广告语境里的泳装大片模特。造型入口：成人广告语境里的泳装大片模特。母题：阳光、度假和身体管理共同包装出的商业性感。张力：她看似自然享受海边，实际每条支撑线和肌肉张力都服务镜头。视觉证据：晒痕、湿发、泳装剪裁、支撑线、面对强光的自信、海滩姿态和健康皮肤。边界：避免写成未成年感、偷拍感或普通海边游客。', defEn: 'First read: a swimwear campaign model inside an adult advertising context. Styling entry: a swimwear campaign model inside an adult advertising context. Motif: commercial glamour packaged by sun, vacation, and body management. Tension: she seems naturally at ease by the sea while every support line and muscle tension serves the camera. Visual evidence: tan marks, wet hair, swimwear cut, support lines, confidence under hard light, beach posture, and healthy skin. Boundary: avoid making it youthful, voyeuristic, or a normal beach tourist.', risk: 'medium', tags: ['swimwear', 'campaign', 'beach'] },
  { id: 'digital_avatar_model', name: '虚拟数字模特', nameEn: 'Virtual Digital Model', group: 'E. 超模 / 模特工业', groupEn: 'E. Supermodel / Model Industry', def: '第一识别是由建模、运营和品牌投放制造出来的虚拟数字模特。造型入口：由建模、运营和品牌投放制造出来的虚拟数字模特。母题：没有真实私生活却拥有公众形象的人造时尚人格。张力：她不是机器人，但皮肤、表情和材质都过于稳定完美。视觉证据：完美数字皮肤、CG服装、虚拟社交账号气质、过稳表情和略微不真实的光洁材料。边界：避免生成机械身体或真人网红。', defEn: 'First read: a virtual digital model manufactured through modeling, operation, and brand deployment. Styling entry: a virtual digital model manufactured through modeling, operation, and brand deployment. Motif: an artificial fashion persona with public image but no real private life. Tension: she is not a robot, yet skin, expression, and materials are too stable and perfect. Visual evidence: flawless digital skin, CG garments, virtual-social-profile aura, over-stable expression, and slightly unreal polished materials. Boundary: avoid generate a mechanical body or real influencer.', ontologyLevel: 3, eras: contemporaryEras, risk: 'medium', tags: ['virtual_model', 'digital', 'brand_avatar'] },

  { id: 'kardashian_reality_socialite', name: '卡戴珊式真人秀名媛', nameEn: 'Kardashian-Style Reality Socialite', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是把私人生活、身体曲线和商业品牌都经营成镜头资产的真人秀名媛。造型入口：把私人生活、身体曲线和商业品牌都经营成镜头资产的真人秀名媛。母题：被持续观看的家族工业身体。张力：她看似暴露日常，实际每个妆容、姿态和服装都在生产可出售的自我。视觉证据：高控制妆发、贴身轮廓、社媒拍摄姿态、奢华家居或活动入口感和习惯被拍的表情。边界：避免写成普通富人或无意识网红。', defEn: 'First read: a reality socialite turning private life, body curves, and personal brands into camera assets. Styling entry: a reality socialite turning private life, body curves, and personal brands into camera assets. Motif: a family-industry body under constant viewing. Tension: she appears to expose daily life while every makeup choice, posture, and garment produces a sellable self. Visual evidence: controlled hair/makeup, body-hugging silhouette, social-media posing, luxury home or event-entrance atmosphere, and a face used to being filmed. Boundary: avoid making her generic rich or accidentally famous.', risk: 'medium', tags: ['reality_tv', 'socialite', 'body_glamour'] },
  { id: 'chaebol_heiress', name: '财阀千金', nameEn: 'Chaebol Heiress', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是被继承权、保镖距离和公开场合训练塑造出来的财阀千金。造型入口：被继承权、保镖距离和公开场合训练塑造出来的财阀千金。母题：家族资本的人形接口。张力：她外表精确冷静，情绪却被家族利益和未来安排压在表面下。视觉证据：定制套装、少装饰珠宝、冷脸、直背、保镖或司机距离和像从小练过的社交姿态。边界：避免写成普通千金小姐或职场女强人。', defEn: 'First read: a chaebol heiress shaped by inheritance pressure, guarded distance, and public-occasion training. Styling entry: a chaebol heiress shaped by inheritance pressure, guarded distance, and public-occasion training. Motif: a human interface for family capital. Tension: she appears precise and cold while emotion is pressed beneath family interest and future arrangement. Visual evidence: tailored suit, minimal jewelry, cold face, straight back, guard or driver distance, and social posture trained since childhood. Boundary: avoid making a generic rich daughter or corporate power woman.', tags: ['chaebol', 'heiress', 'status'] },
  { id: 'dubai_bling_socialite', name: '迪拜富豪名媛', nameEn: 'Dubai Bling Socialite', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是把财富亮度推到画面中心的迪拜式炫耀名媛。造型入口：把财富亮度推到画面中心的迪拜式炫耀名媛。母题：高饱和社媒奢华身体。张力：她不追求克制，而要让钻石、晚礼服和派对入口一起证明资源。视觉证据：强反光珠宝、饱和色礼服、超跑或酒店门廊感、自拍切换姿态和被强光照亮的自信。边界：避免写成静奢旧钱或朴素富人。', defEn: 'First read: a Dubai-style bling socialite pushing wealth brightness to the center of the image. Styling entry: a Dubai-style bling socialite pushing wealth brightness to the center of the image. Motif: a high-saturation social-media luxury body. Tension: she does not seek restraint, but lets diamonds, evening gown, and party entrance prove access. Visual evidence: hard-reflective jewelry, saturated gown, supercar or hotel-portico feeling, selfie-ready posture, and confidence lit by strong light. Boundary: avoid making quiet old money or understated wealth.', risk: 'medium', tags: ['dubai', 'bling', 'socialite'] },
  { id: 'old_money_debutante', name: '旧钱初入社交季少女', nameEn: 'Old-Money Debutante', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是被家族和社交季正式推出的旧钱初入场少女。造型入口：被家族和社交季正式推出的旧钱初入场少女。母题：被阶层认证的青春。张力：年轻感必须被礼仪、白裙和家族珠宝收束，几乎没有私人欲望外溢。视觉证据：白裙、家族珠宝、练习过的微笑、端正站姿、舞会邀请感和清洁到不真实的服装表面。边界：避免写成恋爱少女或现代派对女孩。', defEn: 'First read: an old-money debutante formally presented by family and season. Styling entry: an old-money debutante formally presented by family and season. Motif: class-certified youth. Tension: youth must be contained by etiquette, white dress, and family jewelry, leaving almost no private desire. Visual evidence: white dress, heirloom jewelry, rehearsed smile, proper posture, ball-invitation atmosphere, and clothing surface so clean it feels unreal. Boundary: avoid making a romance girl or modern party girl.', tags: ['old_money', 'debutante', 'class'] },
  { id: 'beverly_hills_mom', name: '比弗利辣妈', nameEn: 'Beverly Hills Mom', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是把日常生活变成昂贵维护项目的比弗利式富裕母亲。造型入口：把日常生活变成昂贵维护项目的比弗利式富裕母亲。母题：健康、保养和消费资源共同生产的轻松身体。张力：她看似刚做完瑜伽顺路买饮品，实际每个细节都在显示持续维护成本。视觉证据：设计师瑜伽裤、巨大墨镜、健康饮品、昂贵手袋、精致脸部和松弛但资源感浓的表情。边界：避免写成普通妈妈或健身教练。', defEn: 'First read: a Beverly Hills wealthy mother turning daily life into an expensive maintenance project. Styling entry: a Beverly Hills wealthy mother turning daily life into an expensive maintenance project. Motif: a relaxed body produced by wellness, beauty upkeep, and consumer access. Tension: she seems to have just left yoga for a drink while every detail reveals ongoing maintenance cost. Visual evidence: designer yoga pants, huge sunglasses, wellness drink, expensive bag, refined face, and relaxed expression thick with resources. Boundary: avoid making a normal mother or fitness instructor.', risk: 'medium', tags: ['beverly_hills', 'mom', 'wellness_luxury'] },
  { id: 'nepo_baby_model', name: '星二代模特', nameEn: 'Nepo Baby Model', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是带着轻松资源和被比较疲惫的星二代模特。造型入口：带着轻松资源和被比较疲惫的星二代模特。母题：名人家族光环下进入行业的年轻身体。张力：她看起来什么都来得容易，却总被质疑天赋是否真实。视觉证据：下班模特穿搭、派对疲惫、昂贵基础款、无意识优越感和眼神里轻微的厌烦。边界：避免写成真正白手起家的新人或普通明星粉丝。', defEn: 'First read: a nepo baby model carrying effortless access and comparison fatigue. Styling entry: a nepo baby model carrying effortless access and comparison fatigue. Motif: a young body entering the industry under celebrity-family halo. Tension: everything seems easy for her while her talent is constantly questioned. Visual evidence: off-duty model styling, party fatigue, expensive basics, unconscious entitlement, and slight irritation in the eyes. Boundary: avoid making a self-made newcomer or ordinary celebrity fan.', tags: ['nepo_baby', 'model', 'celebrity_family'] },
  { id: 'yacht_club_guest', name: '游艇俱乐部客人', nameEn: 'Yacht Club Guest', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是像天生属于码头和会员制假日的游艇俱乐部客人。造型入口：白色亚麻、船鞋、香槟和不讨好人的站姿。母题：海风里的阶层归属感。张力：奢华不靠珠宝堆叠，而靠“这里本来就是我的地方”的松弛姿态。视觉证据：白色亚麻、船鞋、香槟、海风整理过的头发、轻而干净的衣料和不讨好人的站姿。边界：避免度假游客或炫富派对人物。', defEn: 'First read: a yacht-club guest who seems born into marinas and membership holidays. Styling entry: white linen, boat shoes, champagne, and a stance that does not seek approval. Motif: class belonging in sea wind. Tension: luxury comes not from stacked jewelry but from the relaxed posture of “this place is already mine.” Visual evidence: white linen, boat shoes, champagne, wind-arranged hair, light clean fabric, and a stance that does not seek approval. Boundary: avoid a vacation tourist or loud party rich person.', tags: ['yacht', 'vacation', 'old_money'] },
  { id: 'equestrian_socialite', name: '马术名媛', nameEn: 'Equestrian Socialite', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是把马术训练和庄园阶层穿在身上的名媛。造型入口：把马术训练和庄园阶层穿在身上的名媛。母题：纪律化运动传统里的上流身体。张力：她的优雅不是柔软放松，而是背、手、下颌都被长期训练收住。视觉证据：马靴、骑士外套、头盔、手套、庄园或马场接口、直背和稳定手部。边界：避免写成普通骑手或童话贵族。', defEn: 'First read: an equestrian socialite wearing riding discipline and estate class on the body. Styling entry: an equestrian socialite wearing riding discipline and estate class on the body. Motif: an upper-class body inside ritualized sport tradition. Tension: her elegance is not soft ease but a back, hands, and jaw held by long training. Visual evidence: riding boots, equestrian blazer, helmet, gloves, estate or stable interface, straight back, and steady hands. Boundary: avoid making a normal rider or fairy-tale noble.', tags: ['equestrian', 'socialite', 'estate'] },
  { id: 'influencer_billionaire_girlfriend', name: '亿万富豪女友网红', nameEn: 'Billionaire-Girlfriend Influencer', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是把亲密关系、礼物和奢华旅行都运营成内容的富豪女友网红。造型入口：把亲密关系、礼物和奢华旅行都运营成内容的富豪女友网红。母题：被赞助生活方式里的柔顺展示身体。张力：她看似享受爱情和礼物，实际随时在为镜头整理自己。视觉证据：酒店、电梯间或礼物开箱感、自拍姿态、珠宝、柔顺身体语言、精致旅行装和等待被拍的笑容。边界：避免写成普通恋爱角色或独立职业模特。', defEn: 'First read: a billionaire-girlfriend influencer turning intimacy, gifts, and luxury travel into content. Styling entry: a billionaire-girlfriend influencer turning intimacy, gifts, and luxury travel into content. Motif: a compliant display body inside a sponsored lifestyle. Tension: she appears to enjoy love and gifts while constantly arranging herself for camera. Visual evidence: hotel, elevator, or gift-unboxing atmosphere, selfie posture, jewelry, soft body language, polished travel outfit, and a smile waiting to be filmed. Boundary: avoid making a normal romance character or independent professional model.', risk: 'medium', tags: ['influencer', 'luxury_lifestyle', 'socialite'] },
  { id: 'private_school_it_girl', name: '私校It Girl', nameEn: 'Private-School It Girl', group: 'F. 名媛 / 真人秀家族', groupEn: 'F. Socialite / Reality Family', def: '第一识别是校规之内被资源悄悄改造出的私校It Girl。造型入口：校规之内被资源悄悄改造出的私校It Girl。母题：青春阶层秩序里的可见中心。张力：她表面仍是学生，制服细节、书包和小圈子却已经显出校内权力。视觉证据：制服变体、发箍、昂贵书包、干净鞋、社交小团体距离和带轻微优越感的站姿。边界：避免写成普通学生或成人名媛。', defEn: 'First read: a private-school It Girl quietly modified by resources within school rules. Styling entry: a private-school It Girl quietly modified by resources within school rules. Motif: the visible center of youthful class order. Tension: she is still a student on the surface while uniform details, bag, and clique reveal school power. Visual evidence: uniform variation, headband, expensive schoolbag, clean shoes, social-clique spacing, and slightly superior stance. Boundary: avoid making an ordinary student or adult socialite.', tags: ['private_school', 'it_girl', 'class'] },

  { id: 'quiet_luxury_heiress', name: '静奢女继承人', nameEn: 'Quiet Luxury Heiress', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是用无标识面料和克制姿态显示资源的静奢女继承人。造型入口：用无标识面料和克制姿态显示资源的静奢女继承人。母题：不需要解释财富来源的继承身体。张力：服装越安静，阶层压迫感越强。视觉证据：无logo羊绒、低饱和配色、保养发型、简单珠宝、慢而稳的动作和从未需要争取什么的表情。边界：避免写成炫富名媛或普通极简穿搭。', defEn: 'First read: a quiet-luxury heiress showing resources through unbranded fabric and restrained posture. Styling entry: a quiet-luxury heiress showing resources through unbranded fabric and restrained posture. Motif: an inheriting body that never needs to explain where wealth comes from. Tension: the quieter the clothing, the stronger the class pressure. Visual evidence: logo-free cashmere, low-saturation palette, maintained hair, simple jewelry, slow steady movement, and a face that never had to compete. Boundary: avoid making loud wealth or generic minimalist styling.', tags: ['quiet_luxury', 'heiress', 'old_money'] },
  { id: 'country_club_wife', name: '乡村俱乐部太太', nameEn: 'Country Club Wife', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是会员制空间里用礼貌维持门槛的乡村俱乐部太太。造型入口：会员制空间里用礼貌维持门槛的乡村俱乐部太太。母题：日常化的阶层筛选机制。张力：她笑得亲切，身体和衣服却始终提醒别人这里不是公共空间。视觉证据：网球裙、珍珠耳钉、浅色针织、干净球鞋、礼貌微笑和轻轻隔开距离的站姿。边界：避免写成普通运动休闲或家庭主妇。', defEn: 'First read: a country-club wife maintaining thresholds through politeness in a membership space. Styling entry: a country-club wife maintaining thresholds through politeness in a membership space. Motif: everyday class filtering. Tension: she smiles warmly while body and clothing keep reminding others this is not public space. Visual evidence: tennis skirt, pearl studs, pale knitwear, clean sneakers, polite smile, and stance gently keeping distance. Boundary: avoid making generic sport-casual or a normal housewife.', tags: ['country_club', 'wife', 'old_money'] },
  { id: 'east_coast_boarding_school_girl', name: '东海岸寄宿学校女孩', nameEn: 'East-Coast Boarding-School Girl', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是青春被学校、家族和未来履历提前整理过的东海岸寄宿学校女孩。造型入口：青春被学校、家族和未来履历提前整理过的东海岸寄宿学校女孩。母题：纪律管理下的旧钱少女。张力：她年龄很轻，却已经被校徽、规训和家族期待压出端正感。视觉证据：羊毛制服、校徽、旧书、马术照片、压抑站姿、整洁领口和有点疲惫的乖巧。边界：避免写成普通校园少女或叛逆辣妹。', defEn: 'First read: an East-Coast boarding-school girl whose youth has been pre-organized by school, family, and future résumé. Styling entry: an East-Coast boarding-school girl whose youth has been pre-organized by school, family, and future résumé. Motif: an old-money girl under disciplinary management. Tension: she is young, yet crest, rules, and family expectation already make her proper. Visual evidence: wool uniform, school crest, old books, equestrian photos, compressed posture, neat collar, and slightly tired obedience. Boundary: avoid making a normal schoolgirl or rebellious party girl.', tags: ['boarding_school', 'old_money', 'uniform'] },
  { id: 'minimal_gallery_patron', name: '极简画廊赞助人', nameEn: 'Minimal Gallery Patron', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是用沉默、购买和一句评价影响展览命运的极简画廊赞助人。造型入口：用沉默、购买和一句评价影响展览命运的极简画廊赞助人。母题：文化资本里的移动黑色竖线。张力：她不像时尚人物，却比展厅里很多作品更能决定价值。视觉证据：黑色高领、建筑感大衣、艺术展邀请、低声谈话、缓慢扫视和几乎没有装饰的昂贵轮廓。边界：避免写成艺术家或普通看展观众。', defEn: 'First read: a minimal gallery patron who can alter an exhibition through silence, purchase, or one comment. Styling entry: a minimal gallery patron who can alter an exhibition through silence, purchase, or one comment. Motif: a moving black vertical line inside cultural capital. Tension: she is not a fashion figure, yet can decide value more than many works in the room. Visual evidence: black turtleneck, architectural coat, exhibition invitation, low conversation, slow scanning gaze, and an expensive silhouette with almost no decoration. Boundary: avoid making an artist or normal gallery visitor.', tags: ['gallery', 'patron', 'minimal'] },
  { id: 'old_money_ski_resort_heir', name: '滑雪度假旧钱继承人', nameEn: 'Old-Money Ski Resort Heir', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是把滑雪度假当作家族年度习惯的旧钱继承人。造型入口：把滑雪度假当作家族年度习惯的旧钱继承人。母题：祖传假日里的自然归属感。张力：重点不是运动成绩，而是“每年都来这里”的轻松资格。视觉证据：羊绒帽、低调滑雪夹克、山庄壁炉感、健康冷空气肤色、昂贵但不新奇的装备和熟悉场地的松弛姿态。边界：避免写成竞技滑雪选手或旅游网红。', defEn: 'First read: an old-money ski-resort heir treating ski holidays as a family annual habit. Styling entry: an old-money ski-resort heir treating ski holidays as a family annual habit. Motif: natural belonging inside inherited vacation. Tension: the point is not athletic performance but the easy right of coming here every year. Visual evidence: cashmere beanie, understated ski jacket, lodge-fireplace feeling, cold-air healthy complexion, expensive but unflashy gear, and relaxed familiarity with the place. Boundary: avoid making a competitive skier or travel influencer.', tags: ['ski', 'old_money', 'resort'] },
  { id: 'museum_board_lady', name: '博物馆董事女士', nameEn: 'Museum Board Lady', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是能通过捐赠名单和董事会座位管理公共品味的博物馆董事女士。造型入口：能通过捐赠名单和董事会座位管理公共品味的博物馆董事女士。母题：文化机构里的不急不慢权力。张力：她不需要时髦，却比时髦更能决定什么被保存、展出和资助。视觉证据：定制套装、胸针、捐赠名单、保守昂贵细节、疲惫眼神和缓慢点头的判断姿态。边界：避免写成普通贵妇或艺术评论家。', defEn: 'First read: a museum board lady managing public taste through donor lists and board seats. Styling entry: a museum board lady managing public taste through donor lists and board seats. Motif: unhurried power inside cultural institutions. Tension: she does not need to be fashionable, yet decides what is preserved, shown, and funded. Visual evidence: tailored suit, brooch, donor list, conservative expensive detail, tired eyes, and slow nod of judgment. Boundary: avoid making a generic rich lady or art critic.', tags: ['museum', 'board', 'class'] },
  { id: 'stealth_wealth_ceo_spouse', name: '隐形富豪配偶', nameEn: 'Stealth-Wealth CEO Spouse', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是把财富故意压到表面以下的隐形富豪配偶。造型入口：把财富故意压到表面以下的隐形富豪配偶。母题：避开镜头的权力伴随者。张力：没有明显符号，却由面料、剪裁、婚戒和社交退让说明一切。视觉证据：无标识昂贵面料、私人司机距离、简单婚戒、避开镜头的头部角度和克制到近乎消失的穿搭。边界：避免写成炫耀阔太或普通极简白领。', defEn: 'First read: a stealth-wealth CEO spouse deliberately pressing wealth below the surface. Styling entry: a stealth-wealth CEO spouse deliberately pressing wealth below the surface. Motif: a power-adjacent figure avoiding cameras. Tension: there are no obvious signs, yet fabric, cut, wedding ring, and social withdrawal say everything. Visual evidence: unbranded expensive fabric, private-driver distance, simple wedding ring, head angle avoiding cameras, and styling so restrained it nearly disappears. Boundary: avoid making a flashy rich spouse or generic minimalist office worker.', tags: ['stealth_wealth', 'spouse', 'quiet_luxury'] },
  { id: 'literary_prize_socialite', name: '文学奖晚宴名媛', nameEn: 'Literary Prize Dinner Socialite', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是把文学晚宴和文化赞助当成阶层语言使用的名媛。造型入口：把文学晚宴和文化赞助当成阶层语言使用的名媛。母题：会在正确时刻沉默的文化场合身体。张力：她的魅力不靠性感或炫耀，而靠懂得谁该被听见、谁该被介绍。视觉证据：黑色长裙、旧书、红酒、捐赠席位感、克制微笑和手里轻拿邀请函的姿态。边界：避免写成作家本人或普通晚宴客人。', defEn: 'First read: a literary-prize dinner socialite using cultural patronage as class language. Styling entry: a literary-prize dinner socialite using cultural patronage as class language. Motif: a body that knows when to stay silent in cultural rooms. Tension: her appeal comes not from sensuality or display, but from knowing who should be heard and introduced. Visual evidence: black long dress, old books, red wine, donor-seat feeling, restrained smile, and invitation held lightly in hand. Boundary: avoid making her the writer or an ordinary dinner guest.', tags: ['literary', 'dinner', 'socialite'] },
  { id: 'old_money_sailing_daughter', name: '帆船世家女儿', nameEn: 'Old-Money Sailing Daughter', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是带着海风、盐分和家庭俱乐部归属感的帆船世家女儿。造型入口：带着海风、盐分和家庭俱乐部归属感的帆船世家女儿。母题：沿海旧钱的自然骄傲。张力：她不需要派对炫耀，晒痕、针织和不讨好人的自信已经说明出身。视觉证据：海军蓝针织、帆船绳结、晒痕、被风吹乱的发、干净甲板鞋和熟悉海岸的松弛姿态。边界：避免写成普通海边女孩或游艇派对名媛。', defEn: 'First read: an old-money sailing daughter carrying sea wind, salt, and family-club belonging. Styling entry: an old-money sailing daughter carrying sea wind, salt, and family-club belonging. Motif: coastal old-money pride. Tension: she needs no party display, because sun marks, knitwear, and unpleasing confidence already explain origin. Visual evidence: navy knitwear, sailing knots, sun marks, wind-tossed hair, clean deck shoes, and relaxed familiarity with the coast. Boundary: avoid making a generic beach girl or yacht-party socialite.', tags: ['sailing', 'old_money', 'coastal'] },
  { id: 'quiet_luxury_divorcee', name: '静奢离婚贵妇', nameEn: 'Quiet-Luxury Divorcee', group: 'G. 静奢 / 旧钱 / 阶层时尚', groupEn: 'G. Quiet Luxury / Old Money / Class Fashion', def: '第一识别是用更硬的剪裁和更冷的眼神重新划定生活边界的静奢离婚贵妇。造型入口：用更硬的剪裁和更冷的眼神重新划定生活边界的静奢离婚贵妇。母题：切割之后的成熟资源身体。张力：她依然昂贵安静，但每个细节都带有重新分配生活的清醒。视觉证据：剪裁大衣、律师文件、低调珠宝、冷静眼神、紧闭手袋和不再解释的站姿。边界：避免写成伤心弃妇或复仇夸张角色。', defEn: 'First read: a quiet-luxury divorcee redrawing life boundaries through harder tailoring and colder eyes. Styling entry: a quiet-luxury divorcee redrawing life boundaries through harder tailoring and colder eyes. Motif: a mature resource body after separation. Tension: she remains expensive and quiet while every detail carries the clarity of reorganizing life. Visual evidence: tailored coat, legal documents, discreet jewelry, cold gaze, closed handbag, and stance that no longer explains itself. Boundary: avoid making a sad abandoned wife or exaggerated revenge character.', tags: ['divorcee', 'quiet_luxury', 'mature'] },

  { id: 'margiela_anonymous_body', name: 'Margiela匿名身体', nameEn: 'Margiela Anonymous Body', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是脸和名字都退到服装结构后面的匿名身体。造型入口：脸和名字都退到服装结构后面的匿名身体。母题：被缝线、标签和旧衣重组重新编号的载体。张力：角色拒绝明星脸逻辑，却必须保持强烈轮廓记忆。视觉证据：遮脸、白线迹、标签反转、旧衣重构、空白姿态和不通过表情建立身份的身体。边界：避免写成怪物或神秘刺客。', defEn: 'First read: an anonymous body whose face and name retreat behind garment structure. Styling entry: an anonymous body whose face and name retreat behind garment structure. Motif: a carrier renumbered by seams, labels, and reconstructed old clothes. Tension: the figure rejects star-face logic while still needing a strong silhouette memory. Visual evidence: covered face, white stitches, reversed labels, reconstructed garments, blank posture, and a body not built through expression. Boundary: avoid making a monster or mysterious assassin.', ontologyLevel: 2, risk: 'medium', tags: ['margiela', 'anonymous', 'anti_fashion'] },
  { id: 'comme_des_garcons_lump_model', name: 'Comme des Garcons异形衣模特', nameEn: 'Comme des Garcons Lump-Form Model', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是身体轮廓被服装体块重新发明的异形衣模特。造型入口：身体轮廓被服装体块重新发明的异形衣模特。母题：衣服制造出的非标准身体。张力：异常必须来自填充、廓形和不对称剪裁，而不是血肉异变。视觉证据：凸起填充、偏移重心、非标准曲线、压住面孔的服装体积和像艺术物件学习走路的姿态。边界：避免生成真实肿瘤、怪物器官或生物畸变。', defEn: 'First read: a lump-form model whose body outline is reinvented by garment volume. Styling entry: a lump-form model whose body outline is reinvented by garment volume. Motif: a nonstandard body produced by clothing. Tension: abnormality must come from padding, silhouette, and asymmetric cut, not flesh mutation. Visual evidence: padded lumps, shifted center of gravity, nonstandard curves, garment volume overpowering the face, and posture like an art object learning to walk. Boundary: avoid generate real tumors, monster organs, or biological deformity.', ontologyLevel: 2, risk: 'medium', tags: ['cdg', 'lumps', 'art_fashion'] },
  { id: 'anti_fashion_art_student', name: '反时尚艺术学生', nameEn: 'Anti-Fashion Art Student', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是把“不好看”当成立场的反时尚艺术学生。造型入口：把“不好看”当成立场的反时尚艺术学生。母题：学生预算、工作室污痕和理论自信混合出的年轻身体。张力：他不是不会打扮，而是故意拒绝漂亮的可消费性。视觉证据：旧西装、乱扣、油漆痕、二手靴、皱布料和一副知道自己很有理论的表情。边界：避免写成邋遢路人或普通文艺青年。', defEn: 'First read: an anti-fashion art student using unattractiveness as a position. Styling entry: an anti-fashion art student using unattractiveness as a position. Motif: a young body mixed from student budget, studio stains, and theory-heavy confidence. Tension: they are not unable to dress, but deliberately reject consumable prettiness. Visual evidence: old suit, misbuttoning, paint marks, secondhand boots, wrinkled fabric, and a face convinced of its own theory. Boundary: avoid making a sloppy passerby or generic artsy youth.', tags: ['art_student', 'anti_fashion', 'secondhand'] },
  { id: 'deconstructed_office_lady', name: '解构办公室女郎', nameEn: 'Deconstructed Office Lady', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是被办公室制度抽出又用解构剪裁重新缝合的白领女性。造型入口：被办公室制度抽出又用解构剪裁重新缝合的白领女性。母题：职业秩序被时装破坏后的身体。张力：她仍保留工牌、衬衫和西装痕迹，但所有标准线条都开始偏移。视觉证据：错位衬衫、拆线西装、残留工牌、歪斜门襟、偏移肩线和像刚从制度里脱壳的站姿。边界：避免写成普通OL或纯艺术装置。', defEn: 'First read: an office woman pulled from corporate order and re-stitched through deconstructed tailoring. Styling entry: an office woman pulled from corporate order and re-stitched through deconstructed tailoring. Motif: a body after workwear discipline is damaged by fashion. Tension: badge, shirt, and blazer traces remain while every standard line shifts. Visual evidence: displaced shirt, unstitched blazer, ID-card residue, crooked placket, shifted shoulder line, and posture like she just shed an institutional shell. Boundary: avoid making a normal office lady or pure art object.', tags: ['office', 'deconstruction', 'workwear'] },
  { id: 'thrift_store_couture_kid', name: '古着高定青年', nameEn: 'Thrift-Store Couture Kid', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是用二手衣和手改比例自造高定感的年轻人。造型入口：用二手衣和手改比例自造高定感的年轻人。母题：低预算却高自信的街头造型实验者。张力：材料来源混杂，但他真心相信自己穿出了高级系统。视觉证据：旧衣拼接、手改线头、过大肩线、夸张比例、二手外套和年轻到有点莽撞的自信。边界：避免写成真正高定客户或普通古着爱好者。', defEn: 'First read: a youth creating couture feeling from thrifted clothes and hand-altered proportions. Styling entry: a youth creating couture feeling from thrifted clothes and hand-altered proportions. Motif: a low-budget, high-confidence street styling experimenter. Tension: materials come from mixed sources while they fully believe the look has refinement. Visual evidence: thrifted patchwork, hand-altered threads, oversized shoulders, exaggerated proportion, secondhand coat, and young almost reckless confidence. Boundary: avoid making a real couture client or generic vintage shopper.', tags: ['thrift', 'diy_couture', 'youth'] },
  { id: 'post_internet_fashion_weirdo', name: '后互联网时尚怪人', nameEn: 'Post-Internet Fashion Weirdo', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是把梗图、低清打印和社媒审丑穿成时装的后互联网怪人。造型入口：把梗图、低清打印和社媒审丑穿成时装的后互联网怪人。母题：网络图像残渣进入身体造型后的混合体。张力：视觉可以很怪很廉价，但主体必须清楚，不变成纯噪声。视觉证据：错误图案、低清印花、meme服装、廉价数码质感、故意不协调配色和自知的怪趣味表情。边界：避免写成随机乱穿或抽象故障画面。', defEn: 'First read: a post-internet fashion weirdo wearing memes, low-res print, and social-media ugly taste as fashion. Styling entry: a post-internet fashion weirdo wearing memes, low-res print, and social-media ugly taste as fashion. Motif: a hybrid after internet image residue enters body styling. Tension: the look may be weird and cheap while the subject remains clear, not pure noise. Visual evidence: wrong patterns, low-res prints, meme garments, cheap digital texture, deliberately mismatched colors, and self-aware weird taste. Boundary: avoid making random chaos or abstract glitch imagery.', ontologyLevel: 2, risk: 'medium', tags: ['post_internet', 'weird', 'meme'] },
  { id: 'conceptual_black_cloak_figure', name: '概念黑袍人物', nameEn: 'Conceptual Black-Cloak Figure', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是被黑色大体积布料吞没成移动概念的人物。造型入口：被黑色大体积布料吞没成移动概念的人物。母题：拒绝日常功能和可读身份的沉默形体。张力：他像一个观念而不是普通角色，但仍要通过重量、边缘和步伐保持人形存在。视觉证据：黑色大布量、脸部遮蔽、缓慢移动、厚重下摆、吞掉身体细节的轮廓和近乎沉默的姿态。边界：避免写成魔法黑袍或宗教祭司。', defEn: 'First read: a figure swallowed by large black textile volume into a moving concept. Styling entry: a figure swallowed by large black textile volume into a moving concept. Motif: a silent form refusing daily function and readable identity. Tension: they feel like an idea rather than a normal character while still remaining human through weight, edge, and step. Visual evidence: large black fabric, obscured face, slow movement, heavy hem, silhouette swallowing body detail, and nearly silent posture. Boundary: avoid making a magic robe or religious priest.', ontologyLevel: 2, risk: 'medium', tags: ['black_cloak', 'conceptual', 'avant_garde'] },
  { id: 'genderless_runway_rebel', name: '无性别秀场叛逆者', nameEn: 'Genderless Runway Rebel', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是拒绝被性别系统归档的无性别秀场叛逆者。造型入口：拒绝被性别系统归档的无性别秀场叛逆者。母题：从礼服、工装和剪发中拆出新分类的身体。张力：重点不是中性漂亮，而是让多个性别服装系统同时失效。视觉证据：礼服与工装混穿、短发或剃发、模糊身体线、硬肩或软裙并置和不向任何性别提交的站姿。边界：避免写成普通中性美人。', defEn: 'First read: a genderless runway rebel refusing to be filed by gender systems. Styling entry: a genderless runway rebel refusing to be filed by gender systems. Motif: a body making a new category from gowns, workwear, and cut hair. Tension: not neutral prettiness but making several gendered clothing systems fail at once. Visual evidence: mixed gowns and workwear, short or shaved hair, ambiguous body line, hard shoulders beside soft skirt, and stance submitting to no gender code. Boundary: avoid making a generic androgynous beauty.', tags: ['genderless', 'runway', 'rebel'] },
  { id: 'deadstock_fabric_designer', name: '库存布设计师', nameEn: 'Deadstock Fabric Designer', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是把材料限制转化为设计逻辑的库存布设计师。造型入口：把材料限制转化为设计逻辑的库存布设计师。母题：反浪费伦理和手工判断共同构成的创作者身体。张力：布料不统一、来源复杂，却被拼接边界和裁剪逻辑收住。视觉证据：库存面料、环保标签、拼布外套、工作手、材料色差、可见缝线和认真处理边角的姿态。边界：避免写成环保口号人物或普通裁缝。', defEn: 'First read: a deadstock fabric designer turning material limitation into design logic. Styling entry: a deadstock fabric designer turning material limitation into design logic. Motif: a creator body made from anti-waste ethics and hand judgment. Tension: fabrics mismatch and sources are complex, yet patch boundaries and cutting logic hold them together. Visual evidence: deadstock textiles, eco labels, patchwork coat, working hands, material color differences, visible seams, and posture carefully handling edges. Boundary: avoid making an eco slogan figure or generic tailor.', tags: ['deadstock', 'designer', 'sustainability'] },
  { id: 'runway_performance_artist', name: '秀场行为艺术家', nameEn: 'Runway Performance Artist', group: 'H. 解构 / 先锋 / 反时尚', groupEn: 'H. Deconstruction / Avant-Garde / Anti-Fashion', def: '第一识别是用身体让服装变成事件的秀场行为艺术家。造型入口：用身体让服装变成事件的秀场行为艺术家。母题：走台被改造成表演行为后的非标准模特。张力：动作可以怪、夸张甚至让观众不适，但必须有清楚的表演逻辑。视觉证据：非标准步伐、突兀停顿、夸张手势、服装被动作牵动的结构和不为展示漂亮而服务的表情。边界：避免写成失控疯癫或普通舞者。', defEn: 'First read: a runway performance artist using the body to turn clothing into an event. Styling entry: a runway performance artist using the body to turn clothing into an event. Motif: a nonstandard model after runway walking becomes performance. Tension: movement may be strange, exaggerated, even uncomfortable, but must have clear performance logic. Visual evidence: nonstandard walk, abrupt pauses, exaggerated hands, clothing structures activated by motion, and a face not serving prettiness. Boundary: avoid making uncontrolled madness or a generic dancer.', ontologyLevel: 2, risk: 'medium', tags: ['performance', 'runway', 'avant_garde'] },

  { id: 'goth_couture_heir', name: '哥特高定继承人', nameEn: 'Goth Couture Heir', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是继承冷宅、血统和丧服制度的哥特高定继承人。造型入口：继承冷宅、血统和丧服制度的哥特高定继承人。母题：家族遗产把黑暗训练成礼仪的上流身体。张力：情绪被压住，但苍白妆面和黑色高定仍泄出阴影。视觉证据：黑色礼服、苍白脸、珠宝十字感配饰、疏离礼仪、端正站姿和像刚从遗产文件旁走来的冷感。边界：避免写成恐怖角色或普通哥特女孩。', defEn: 'First read: a goth couture heir inheriting a cold estate, bloodline, and mourning system. Styling entry: a goth couture heir inheriting a cold estate, bloodline, and mourning system. Motif: an upper-class body where family legacy trains darkness into etiquette. Tension: emotion is held down while pale makeup and black couture leak shadow. Visual evidence: black gown, pale face, jeweled cross-like accessory, distant manners, proper stance, and a chill as if arriving from inheritance documents. Boundary: avoid making a horror character or generic goth girl.', ontologyLevel: 2, risk: 'medium', tags: ['goth', 'couture', 'heir'] },
  { id: 'religious_vestment_couture_model', name: '宗教法衣高定模特', nameEn: 'Religious Vestment Couture Model', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是把法衣结构转译成秀场制度的高定模特。造型入口：把法衣结构转译成秀场制度的高定模特。母题：神圣感被时装化后的垂直身体。张力：庄严正面性来自衣片、金线和姿态，而不是直接复制真实宗教。视觉证据：垂直衣片、金线刺绣、冷白妆面、圣像式正面站姿和金属线工艺。边界：避免照搬真实宗教符号或具体仪式。', defEn: 'First read: a couture model translating vestment structure into runway order. Styling entry: a couture model translating vestment structure into runway order. Motif: a vertical body after sacredness is fashionized. Tension: solemn frontality comes from panels, gold thread, and posture rather than direct religious copying. Visual evidence: vertical garment panels, gold embroidery, pale makeup, icon-like frontal stance, and metal-thread craft. Boundary: avoid copy real religious symbols or specific rituals.', ontologyLevel: 2, risk: 'medium', tags: ['vestment', 'couture', 'ritual'] },
  { id: 'black_mass_socialite', name: '黑色弥撒名媛', nameEn: 'Black Mass Socialite', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是把禁忌晚宴变成上流活动的黑色弥撒名媛。造型入口：把禁忌晚宴变成上流活动的黑色弥撒名媛。母题：黑暗感经过礼服、餐桌和社交礼仪过滤后的社交身体。张力：她危险但不恐怖，笑容像邀请也像排除。视觉证据：黑纱、烛光珠宝、哥特礼服、餐桌边缘、危险社交微笑和过分优雅的手势。边界：避免写成邪教祭司或恐怖片人物。', defEn: 'First read: a black-mass socialite turning taboo dinner into an upper-class event. Styling entry: a black-mass socialite turning taboo dinner into an upper-class event. Motif: a social body where darkness is filtered through gown, table, and etiquette. Tension: she feels dangerous but not horrific, her smile both inviting and excluding. Visual evidence: black veil, candlelit jewelry, gothic gown, table edge, dangerous social smile, and excessively elegant hands. Boundary: avoid making a cult priestess or horror-film figure.', ontologyLevel: 3, risk: 'medium', tags: ['black_mass', 'socialite', 'gothic'] },
  { id: 'iconic_red_carpet_saint', name: '圣像式红毯女星', nameEn: 'Iconic Red-Carpet Saint', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是被红毯媒体神化成现代圣像的女星。造型入口：被红毯媒体神化成现代圣像的女星。母题：明星工业制造出的可供凝视的神圣姿态。张力：神圣感来自光、正面性和礼服祭坛感，而非真实宗教身份。视觉证据：光环式头饰、金色礼服、正面站姿、静止面孔、正光和像祭坛一样铺开的服装。边界：避免写成真正圣徒或普通金色礼服明星。', defEn: 'First read: a red-carpet star deified by media into a modern icon. Styling entry: a red-carpet star deified by media into a modern icon. Motif: sacred posture manufactured by star industry for viewing. Tension: holiness comes from light, frontality, and gown-as-altar, not real religious identity. Visual evidence: halo-like headpiece, gold gown, frontal stance, still face, direct light, and clothing spreading like an altar. Boundary: avoid making a real saint or generic gold-gown celebrity.', ontologyLevel: 3, risk: 'medium', tags: ['saint', 'red_carpet', 'icon'] },
  { id: 'mourning_lace_countess', name: '黑蕾丝丧服伯爵夫人', nameEn: 'Black-Lace Mourning Countess', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是把哀悼变成阶层表演的黑蕾丝丧服伯爵夫人。造型入口：把哀悼变成阶层表演的黑蕾丝丧服伯爵夫人。母题：财产、称号和悲伤共同压出的贵族身体。张力：她像在伤心，却每个手势都被礼仪和继承秩序拉长。视觉证据：黑蕾丝、长手套、丧礼珠宝、遮蔽皮肤、拉长手势和带重量的沉默表情。边界：避免写成鬼魂或普通复古贵妇。', defEn: 'First read: a black-lace mourning countess turning grief into class performance. Styling entry: a black-lace mourning countess turning grief into class performance. Motif: an aristocratic body pressed by property, title, and sadness. Tension: she seems to grieve while every gesture is elongated by etiquette and inheritance order. Visual evidence: black lace, long gloves, mourning jewels, concealed skin, lengthened hands, and weighted silent expression. Boundary: avoid making a ghost or generic vintage lady.', ontologyLevel: 1, tags: ['mourning', 'lace', 'countess'] },
  { id: 'latex_nun_couture', name: '乳胶修女高定', nameEn: 'Latex Nun Couture', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是用修女头巾轮廓和乳胶材质制造禁欲/挑衅并置的高定人物。造型入口：头巾式轮廓、黑色乳胶和覆盖皮肤的结构。母题：遮蔽结构被时装化后的成人造型实验。张力：材质挑衅，但表情和构图必须冷静克制。视觉证据：头巾式轮廓、黑色乳胶、圣物感配饰、覆盖皮肤的结构和冷静正面脸。边界：避免真实宗教冒犯、色情角色或真正修女。', defEn: 'First read: a couture figure using nun-habit silhouette and latex material to stage abstinence against provocation. Styling entry: habit-like outline, black latex, and skin-covering structure. Motif: an adult styling experiment after concealment structure is fashionized. Tension: the material provokes while expression and framing stay calm and restrained. Visual evidence: habit-like outline, black latex, sacred-object-like accessories, skin-covering structure, and calm frontal face. Boundary: avoid real religious offense, pornography, or an actual nun.', ontologyLevel: 2, risk: 'medium', tags: ['nun', 'latex', 'couture'] },
  { id: 'cathedral_runway_bride', name: '教堂秀场新娘', nameEn: 'Cathedral Runway Bride', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是被教堂长廊、超长头纱和秀场步伐共同拖长的白色新娘。造型入口：被教堂长廊、超长头纱和秀场步伐共同拖长的白色新娘。母题：建筑、仪式和高定压出的婚礼命运。张力：她不是甜美恋爱新娘，而像被白色结构推向公开献祭的中心。视觉证据：超长头纱、白色刺绣、庄严慢步、长廊感、压住肩颈的礼服重量和安静到不快乐的脸。边界：避免写成普通婚纱写真。', defEn: 'First read: a white bride stretched by cathedral aisle, extreme veil, and runway pace. Styling entry: a white bride stretched by cathedral aisle, extreme veil, and runway pace. Motif: bridal fate pressed by architecture, ritual, and couture. Tension: she is not a sweet romantic bride but the center of a public offering pushed forward by white structure. Visual evidence: extreme veil, white embroidery, solemn slow walk, aisle feeling, gown weight pressing neck and shoulders, and a face quiet rather than happy. Boundary: avoid making a generic bridal shoot.', ontologyLevel: 2, risk: 'medium', tags: ['cathedral', 'bride', 'ritual'] },
  { id: 'rosary_goth_model', name: '玫瑰念珠哥特模特', nameEn: 'Rosary Goth Model', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是把念珠和黑白材质对比做成配饰系统的哥特模特。造型入口：把念珠和黑白材质对比做成配饰系统的哥特模特。母题：宗教符号被时尚化后的颈部与手部造型。张力：符号要像可穿戴装饰，不进入真实仪式复制。视觉证据：多层念珠、黑唇、蕾丝手套、苍白面部、颈部堆叠和手指停在珠串上的动作。边界：避免写成虔诚信徒或恐怖巫术人物。', defEn: 'First read: a rosary goth model turning beads and black-white material contrast into an accessory system. Styling entry: a rosary goth model turning beads and black-white material contrast into an accessory system. Motif: neck-and-hand styling after religious signs are fashionized. Tension: symbols must read as wearable decoration, not copied ritual. Visual evidence: layered rosaries, black lips, lace gloves, pale face, neck stacking, and fingers paused on beads. Boundary: avoid making a devout believer or horror occult figure.', ontologyLevel: 2, risk: 'medium', tags: ['rosary', 'goth', 'model'] },
  { id: 'vampire_couture_socialite', name: '吸血鬼高定名媛', nameEn: 'Vampire Couture Socialite', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是上流夜宴中过度优雅、带轻微非人魅力的吸血鬼高定名媛。造型入口：上流夜宴中过度优雅、带轻微非人魅力的吸血鬼高定名媛。母题：危险被古董质感和社交礼仪压低后的夜生活身体。张力：她不是怪物突袭，而是把危险藏进微笑和脖颈。视觉证据：红黑礼服、苍白皮肤、古董珠宝、夜宴姿态、冷静微笑和略微过长的凝视。边界：避免生成血腥怪物或动作攻击场面。', defEn: 'First read: a vampire couture socialite, overly elegant in upper-class nightlife with slight nonhuman allure. Styling entry: a vampire couture socialite, overly elegant in upper-class nightlife with slight nonhuman allure. Motif: danger lowered by antique texture and social etiquette. Tension: she is not a monster attack, but hides danger in smile and neck. Visual evidence: red-black gown, pale skin, antique jewelry, nocturnal dinner posture, calm smile, and slightly too-long gaze. Boundary: avoid generate gore monster or attack action.', ontologyLevel: 3, risk: 'medium', tags: ['vampire', 'couture', 'socialite'] },
  { id: 'baroque_saint_model', name: '巴洛克圣徒模特', nameEn: 'Baroque Saint Model', group: 'I. 宗教 / 哥特 / 仪式高定', groupEn: 'I. Religious / Gothic / Ritual Couture', def: '第一识别是被巴洛克绘画戏剧性和高定造型共同制造的圣徒式模特。造型入口：被巴洛克绘画戏剧性和高定造型共同制造的圣徒式模特。母题：痛苦、金色和光线组成的秀场神迹。张力：情绪可以夸张，但身体必须像被摆放过一样稳定。视觉证据：金色刺绣、痛苦仰头、戏剧光、圣物式道具、强烈衣褶和被光固定住的姿态。边界：避免写成真实宗教圣徒或失控哭喊人物。', defEn: 'First read: a saint-like model produced by Baroque painting drama and couture styling together. Styling entry: a saint-like model produced by Baroque painting drama and couture styling together. Motif: a runway miracle made of pain, gold, and light. Tension: emotion may be exaggerated while the body remains placed and stable. Visual evidence: gold embroidery, pained upward head, dramatic light, relic-like props, strong folds, and posture fixed by illumination. Boundary: avoid making a real religious saint or uncontrolled crying figure.', ontologyLevel: 3, risk: 'medium', tags: ['baroque', 'saint', 'couture'] },

  { id: 'runway_stylist', name: '秀场造型师', nameEn: 'Runway Stylist', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是混乱后台里用手和时间控制秀场出口的造型师。造型入口：混乱后台里用手和时间控制秀场出口的造型师。母题：把模特推上幕布前一秒的人。张力：她不站在聚光灯下，却用整理衣领、卡住节奏和耳机指令决定画面是否成立。视觉证据：黑色工作服、别针、样衣架、耳机、急而准的手和在混乱中冷静的脸。边界：避免写成走秀模特或普通穿搭顾问。', defEn: 'First read: a runway stylist controlling backstage exit through hands and timing. Styling entry: a runway stylist controlling backstage exit through hands and timing. Motif: the person who sends models through the curtain one second before showtime. Tension: she is not under the spotlight yet decides whether the image works through collar fixes, timing, and earpiece instructions. Visual evidence: black workwear, pins, sample racks, earpiece, urgent precise hands, and a calm face inside chaos. Boundary: avoid making a runway model or casual styling advisor.', tags: ['stylist', 'backstage', 'labor'] },
  { id: 'sample_garment_worker', name: '样衣服装工', nameEn: 'Sample Garment Worker', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是高定背后赶制样衣的服装劳动者。造型入口：高定背后赶制样衣的服装劳动者。母题：华丽成品之前的手工压力身体。张力：她不需要穿得漂亮，手、围裙、线头和眼下疲劳才是真正的设计证据。视觉证据：软尺、针线、粉笔痕、疲惫手部、围裙、线头和被截止时间压住的肩颈。边界：避免写成高定模特或浪漫裁缝。', defEn: 'First read: a garment worker making samples behind couture. Styling entry: a garment worker making samples behind couture. Motif: a craft-pressure body before the glamorous finished piece. Tension: she need not dress beautifully because hands, apron, threads, and under-eye fatigue are the real design evidence. Visual evidence: measuring tape, thread, chalk marks, tired hands, apron, loose threads, and shoulders pressed by deadline. Boundary: avoid making a couture model or romantic tailor.', tags: ['garment_worker', 'sample', 'atelier'] },
  { id: 'fashion_buyer', name: '时装买手', nameEn: 'Fashion Buyer', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是在美感和销售之间冷静计算的时装买手。造型入口：在美感和销售之间冷静计算的时装买手。母题：能从一件衣服里读出库存、客群和利润的人。张力：她看似欣赏服装，实际每个试穿判断都连接商业风险。视觉证据：订货表、平板、展厅灯光、试穿观察、冷静眼神和停在衣料上的评估手势。边界：避免写成购物狂或单纯时尚编辑。', defEn: 'First read: a fashion buyer calculating calmly between beauty and sales. Styling entry: a fashion buyer calculating calmly between beauty and sales. Motif: someone who can read inventory, audience, and profit from a garment. Tension: she appears to admire clothing while every fitting judgment links to commercial risk. Visual evidence: order sheets, tablet, showroom lighting, fitting observation, calm eyes, and evaluative hand paused on fabric. Boundary: avoid making a shopping addict or pure fashion editor.', tags: ['buyer', 'showroom', 'commerce'] },
  { id: 'backstage_makeup_artist', name: '后台化妆师', nameEn: 'Backstage Makeup Artist', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是几十秒内把一张脸推上秀场的后台化妆师。造型入口：几十秒内把一张脸推上秀场的后台化妆师。母题：靠近面部工作的快速技术身体。张力：她本人隐入黑衣和工具，权力集中在稳定下巴与完成眼神的两只手上。视觉证据：刷具腰包、手背试色、黑衣、靠近脸部的专注、快速眼妆和模特脸旁的手部距离。边界：避免写成美妆博主或被化妆的人。', defEn: 'First read: a backstage makeup artist pushing a face onto the runway within seconds. Styling entry: a backstage makeup artist pushing a face onto the runway within seconds. Motif: a fast technical body working near faces. Tension: she disappears into black clothing and tools while power concentrates in the hands steadying a chin and finishing a gaze. Visual evidence: brush belt, hand swatches, black clothing, close facial focus, fast eye makeup, and hand-face distance beside a model. Boundary: avoid making a beauty influencer or the person receiving makeup.', tags: ['makeup_artist', 'backstage', 'tools'] },
  { id: 'brand_visual_director', name: '品牌视觉总监', nameEn: 'Brand Visual Director', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是把颜色、模特、空间和广告图像压成同一个品牌世界的视觉总监。造型入口：把颜色、模特、空间和广告图像压成同一个品牌世界的视觉总监。母题：图像方向的总控者。张力：她不必亲自制作任何东西，却用低声指令改变所有人手里的画面。视觉证据：情绪板、样片、全黑套装、低声指挥、冷静总控眼神和周围人等待判断的空间关系。边界：避免写成普通设计师或摄影师。', defEn: 'First read: a brand visual director compressing color, models, space, and campaign images into one brand world. Styling entry: a brand visual director compressing color, models, space, and campaign images into one brand world. Motif: the controller of image direction. Tension: she may make nothing by hand, yet her low instructions alter everyone else’s image. Visual evidence: moodboards, contact sheets, all-black outfit, quiet directing, cold total-control gaze, and people around her waiting for judgment. Boundary: avoid making a generic designer or photographer.', tags: ['visual_director', 'brand', 'moodboard'] },
  { id: 'fashion_show_producer', name: '时装秀制作人', nameEn: 'Fashion Show Producer', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是让秀准时开始、把现场系统压住的时装秀制作人。造型入口：让秀准时开始、把现场系统压住的时装秀制作人。母题：流程、场地和危机处理构成的人。张力：她不是造型中心，却是所有造型能否被看见的条件。视觉证据：对讲机、时间表、场地图、实用黑衣、紧绷面部和像“还有三分钟”一样压缩的身体。边界：避免写成模特、主持人或活动嘉宾。', defEn: 'First read: a fashion show producer holding the live system together so the show starts on time. Styling entry: a fashion show producer holding the live system together so the show starts on time. Motif: a person made from schedule, venue, and crisis handling. Tension: she is not the styling center, yet is the condition for all styling to be seen. Visual evidence: walkie-talkie, schedule, venue map, practical black clothing, tense face, and a body compressed by “three minutes left”. Boundary: avoid making a model, host, or guest.', tags: ['producer', 'show', 'logistics'] },
  { id: 'atelier_premiere', name: '高定工坊首席裁缝', nameEn: 'Couture Atelier Premiere', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是能判断一毫米线条是否成立的高定工坊首席裁缝。造型入口：能判断一毫米线条是否成立的高定工坊首席裁缝。母题：手工秩序里的沉默法官。张力：她衣着干净朴素，却拥有决定华丽礼服成败的技术权威。视觉证据：白袍、针插、立裁布胚、经验手、沉默眼神和检查布线时极小的手部动作。边界：避免写成普通缝纫工或高定贵妇。', defEn: 'First read: a couture atelier premiere who can judge whether a one-millimeter line works. Styling entry: a couture atelier premiere who can judge whether a one-millimeter line works. Motif: a silent judge inside craft order. Tension: her own clothing is clean and plain while she holds the technical authority deciding the fate of glamorous gowns. Visual evidence: white coat, pincushion, draped toile, experienced hands, silent eyes, and tiny hand movements checking fabric lines. Boundary: avoid making a generic sewer or couture lady.', tags: ['atelier', 'tailor', 'craft'] },
  { id: 'fashion_week_intern', name: '时装周实习生', nameEn: 'Fashion Week Intern', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是被时装周后台吞进去、还没有权力的实习生。造型入口：被时装周后台吞进去、还没有权力的实习生。母题：任务、熬夜和野心堆出来的行业入口身体。张力：她穿得努力接近行业黑色制服，却仍露出便宜、年轻和紧张。视觉证据：过大工牌、咖啡、黑色便鞋、跑动姿态、廉价实用衣服、睡眠不足和想被看见的眼神。边界：避免写成正式造型师或普通学生。', defEn: 'First read: a fashion-week intern swallowed by backstage with no power yet. Styling entry: a fashion-week intern swallowed by backstage with no power yet. Motif: an entry-level industry body built from tasks, sleeplessness, and ambition. Tension: she tries to approximate the industry’s black uniform while still showing cheapness, youth, and nerves. Visual evidence: oversized badge, coffee, black flats, running posture, practical cheap clothes, lack of sleep, and eyes wanting to be noticed. Boundary: avoid making a full stylist or normal student.', tags: ['intern', 'fashion_week', 'labor'] },
  { id: 'model_agent', name: '模特经纪人', nameEn: 'Model Agent', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是站在模特身体和市场价格之间的经纪人。造型入口：站在模特身体和市场价格之间的经纪人。母题：保护与利用并存的职业中介。张力：他看似冷静照顾人，实际永远在计算下一通电话、下一张资料卡和下一份合同。视觉证据：资料卡、手机、冷静交易姿态、疲惫眼神、紧贴身体的文件包和不完全温柔的表情。边界：避免写成经纪公司新人或普通商务人。', defEn: 'First read: a model agent standing between model bodies and market price. Styling entry: a model agent standing between model bodies and market price. Motif: a professional intermediary mixing protection and exploitation. Tension: he seems to care calmly while always calculating the next call, comp card, and contract. Visual evidence: comp cards, phone, calm negotiation posture, tired eyes, close-held document bag, and an expression not fully kind. Boundary: avoid making an agency newcomer or generic businessperson.', tags: ['agent', 'model', 'business'] },
  { id: 'luxury_personal_shopper', name: '奢侈品私人买手', nameEn: 'Luxury Personal Shopper', group: 'J. 时尚后台 / 职业时尚', groupEn: 'J. Fashion Backstage / Professional Fashion', def: '第一识别是用柔软服务姿态掌握客户尺寸、秘密和预算的奢侈品私人买手。造型入口：用柔软服务姿态掌握客户尺寸、秘密和预算的奢侈品私人买手。母题：高端零售里的亲密控制者。张力：她看似礼貌退后，实际知道顾客身体和消费欲望的细节。视觉证据：白手套、购物袋、客户档案、试衣间礼貌、整洁低调制服和半弯身递衣的姿态。边界：避免写成普通导购或富太本人。', defEn: 'First read: a luxury personal shopper using soft service posture while knowing the client’s size, secrets, and budget. Styling entry: a luxury personal shopper using soft service posture while knowing the client’s size, secrets, and budget. Motif: an intimate controller inside high-end retail. Tension: she appears politely withdrawn while knowing details of a customer’s body and desire to spend. Visual evidence: white gloves, shopping bags, client files, fitting-room politeness, neat subdued uniform, and half-bent posture offering garments. Boundary: avoid making a normal salesperson or the wealthy client herself.', tags: ['personal_shopper', 'luxury', 'client'] }
];

export const CD_PERSONA_FASHION: PersonaTerm[] = seeds.map(fp);
